window.ATLAS_ITEMS=window.ATLAS_ITEMS||{};window.ATLAS_ITEMS[363]={"id":"363","numero":363,"titre":"Fractures fréquentes","objectifs":[{"id":"363-1","rang":"B","rubrique":"Epidémiologie","titre":"Connaître l’épidémiologie des fractures de l’extrémité inférieure du radius (EIR) et de l’extrémité proximale du fémur","contenu":"<p>Deux fractures <strong>« fréquentes »</strong> liées à l'<span class=\"kw-etio\">ostéoporose</span> et à la <span class=\"kw-etio\">chute du sujet âgé</span>, avec dans <span class=\"kw-clinique\">les</span> deux cas une <span class=\"kw-def\">distribution bimodale</span> (sujet jeune / haute énergie <span class=\"kw-bio\">vs</span> sujet âgé / basse énergie).</p>\n\n      <h4 class=\"kw-def\">Fractures de l'extrémité supérieure du fémur (FESF)</h4>\n      <ul>\n        <li><strong>Fréquence</strong> : <span class=\"kw-chiffre\">≈ 90 000 cas/an</span> en France ; nombre attendu en <span class=\"kw-bio\">forte hausse</span> avec le vieillissement (projection ancienne : ×3 d'ici 2050, révisée à la baisse).</li>\n        <li><strong><span class=\"kw-def\">Terrain</span></strong> : <span class=\"kw-clinique\">sujet âgé</span>, <span class=\"kw-bio\">prédominance féminine</span> (<span class=\"kw-etio\">ostéoporose</span> + longévité), traumatisme à <span class=\"kw-def\">basse énergie</span> (chute de sa hauteur).</li>\n        <li><strong>Sujet jeune</strong> : rare, traumatisme à <span class=\"kw-def\">haute énergie</span> (AVP, chute d'un lieu élevé).</li>\n        <li><strong><span class=\"kw-def\">Pronostic</span> à<span class=\"kw-chiffre\"> 1 an</span></strong> (reflet des <span class=\"kw-def\">comorbidités</span>, <span class=\"kw-alerte\">sévère surtout chez l'homme</span>) : <span class=\"kw-chiffre\">15-20 %</span> de <span class=\"kw-def\">mortalité</span>, <span class=\"kw-chiffre\">20-25 %</span> d'institutionnalisation, <span class=\"kw-chiffre\">40-60 %</span> de perte d'autonomie motrice.</li>\n        <li><strong>Surmortalité</strong> globale de l'ordre de <span class=\"kw-chiffre\">20 % à 1 an</span> ⇒ <span class=\"kw-alerte\">problème de santé publique</span>, à <span class=\"kw-ci\">ne jamais</span> banaliser.</li>\n      </ul>\n\n      <h4 class=\"kw-def\">Fractures de l'extrémité inférieure du radius (EIR)</h4>\n      <ul>\n        <li><strong>Fréquence</strong> : <span class=\"kw-bio\">lésion osseuse traumatique la plus fréquente</span> (devant <span class=\"kw-clinique\">les</span> FESF) ; <span class=\"kw-bio\">2ᵉ localisation fracturaire de l'ostéoporose</span> (après le rachis).</li>\n        <li><strong>2 pics de fréquence</strong> :\n          <ul>\n            <li><span class=\"kw-clinique\">Sujet jeune</span> (<span class=\"kw-chiffre\">&lt; 40 ans</span>), prédominance <span class=\"kw-bio\">masculine</span>, <span class=\"kw-def\">haute énergie</span> → plutôt fractures <span class=\"kw-imagerie\">articulaires</span>.</li>\n            <li><span class=\"kw-clinique\">Sujet âgé</span> (<span class=\"kw-chiffre\">&gt; 40 ans</span>), prédominance <span class=\"kw-bio\">féminine</span>, <span class=\"kw-def\">basse énergie</span> → plutôt fractures <span class=\"kw-imagerie\">sus-articulaires</span> (métaphysaires).</li>\n          </ul>\n        </li>\n      </ul>","frequence":0},{"id":"363-2","rang":"B","rubrique":"Physiopathologie","titre":"Connaître les mécanismes lésionnels de l’extrémité proximale du fémur","contenu":"<h4 class=\"kw-def\">Mécanismes selon l'énergie</h4>\n      <table >\n        <thead><tr><th>Mécanisme</th><th>Contexte</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong><span class=\"kw-def\">Haute énergie</span></strong></td>\n            <td><span class=\"kw-etio\">AVP</span> par <span class=\"kw-clinique\">syndrome du tableau de bord</span> : compression transmise du genou au fémur jusqu'à l'extrémité supérieure.</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-def\">Basse énergie</span></strong></td>\n            <td><span class=\"kw-etio\">Chute de sa hauteur</span> sur os pathologique : <span class=\"kw-etio\">ostéoporose</span> (sujet âgé ++), ou <span class=\"kw-etio\">tumeur</span> / <span class=\"kw-etio\">maladie de Paget</span> / <span class=\"kw-etio\">trouble du métabolisme osseux</span> chez le sujet jeune.</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4 class=\"kw-def\">Deux entités aux conditions vasculaires et mécaniques opposées</h4>\n      <table >\n        <thead><tr><th></th><th>Fractures cervicales (col)</th><th>Fractures trochantériennes</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Type d'os</strong></td><td><span class=\"kw-def\">Os cortical dense</span></td><td><span class=\"kw-def\">Os spongieux</span></td></tr>\n          <tr><td><strong>Situation</strong></td><td><span class=\"kw-imagerie\">Intra-articulaire</span></td><td><span class=\"kw-imagerie\">Extra-articulaire</span></td></tr>\n          <tr><td><strong>Forces</strong></td><td><span class=\"kw-def\">Cisaillement</span> prédominant</td><td><span class=\"kw-def\">Compression</span> prédominante</td></tr>\n          <tr><td><strong>Vascularisation</strong></td><td><span class=\"kw-alerte\">Fragile</span></td><td><span class=\"kw-bio\">Riche</span></td></tr>\n          <tr><td><strong>Consolidation</strong></td><td><span class=\"kw-chiffre\">Longue (≈ 4 mois)</span></td><td><span class=\"kw-chiffre\">≈ 40 jours</span></td></tr>\n          <tr><td><strong>Complications</strong></td><td><span class=\"kw-alerte\">Nécrose ischémique</span> de la tête, <span class=\"kw-alerte\">pseudarthrose</span></td><td><span class=\"kw-alerte\">Cal vicieux</span> (rotation externe, adduction, raccourcissement)</td></tr>\n        </tbody>\n      </table>\n\n      <h4 class=\"kw-def\">Vascularisation de la tête fémorale — clé du <span class=\"kw-def\">pronostic</span></h4>\n      <ul>\n        <li>Apport <strong>majeur</strong> = <span class=\"kw-def\">artère circonflexe fémorale médiale</span> (branche de la fémorale profonde) via <span class=\"kw-clinique\">les</span> <span class=\"kw-bio\">vaisseaux rétinaculaires / capsulaires</span>.</li>\n        <li>Apports mineurs : <span class=\"kw-def\">artère circonflexe latérale</span> (col) et <span class=\"kw-def\">artère du ligament rond</span> (peu fonctionnelle chez l'adulte).</li>\n        <li>Une <span class=\"kw-clinique\">fracture du col déplacée</span> rompt <span class=\"kw-clinique\">les</span> vaisseaux capsulaires ⇒ <span class=\"kw-alerte\">ostéonécrose avasculaire</span> de la tête, d'autant plus que le déplacement est important (<span class=\"kw-alerte\">rupture</span> de la capsule).</li>\n      </ul>","frequence":0,"liens":[{"href":"https://radiopaedia.org/articles/proximal-femoral-fractures","label":"Radiopaedia : Proximal femoral fractures"},{"href":"https://radiopaedia.org/cases/femoral-head-blood-supply","label":"Radiopaedia : Vascularisation de la tête fémorale"}]},{"id":"363-3","rang":"A","rubrique":"Diagnostic positif","titre":"Savoir faire le diagnostic clinique de fracture du fémur proximal","contenu":"<p><strong>Contexte</strong> : <span class=\"kw-etio\">chute de sa hauteur</span> (basse énergie) ou <span class=\"kw-etio\">AVP</span> (syndrome du tableau de bord).</p>\n\n      <h4 class=\"kw-def\">Signes cliniques</h4>\n      <ul>\n        <li><span class=\"kw-clinique\">Douleur</span> : de l'<span class=\"kw-clinique\">aine</span> (fracture cervicale) ou du <span class=\"kw-clinique\">grand trochanter</span> (fracture trochantérienne).</li>\n        <li><span class=\"kw-clinique\">Impotence fonctionnelle</span> du membre inférieur : <span class=\"kw-clinique\">appui possible</span> si <span class=\"kw-imagerie\">Garden 1/2</span> ; <span class=\"kw-alerte\">impotence fonctionnelle totale</span> si <span class=\"kw-imagerie\">Garden 3/4</span> ou fracture trochantérienne.</li>\n        <li><span class=\"kw-clinique\">Clinostatisme</span> : impossibilité de <span class=\"kw-clinique\">décoller le talon du plan du lit</span>.</li>\n      </ul>\n\n      <h4 class=\"kw-def\">Attitude vicieuse typique (fractures déplacées)</h4>\n      <ul>\n        <li><strong><span class=\"kw-clinique\">Raccourcissement</span> + <span class=\"kw-clinique\">adduction</span> + <span class=\"kw-clinique\">rotation externe</span></strong> (le bord externe du pied repose sur la table).</li>\n        <li><span class=\"kw-alerte\">Piège</span> : l'attitude vicieuse <strong>peut manquer</strong> dans <span class=\"kw-clinique\">les</span> fractures <span class=\"kw-imagerie\">Garden 1/2</span> (peu déplacées).</li>\n        <li>À distinguer de la <span class=\"kw-def\">luxation de hanche</span> = attitude <strong>inverse</strong> (allongement, rotation interne).</li>\n      </ul>\n\n      <table >\n        <thead><tr><th></th><th>Fracture cervicale vraie</th><th>Fracture trochantérienne</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Douleur</strong></td><td><span class=\"kw-clinique\">Aine</span></td><td><span class=\"kw-clinique\">Grand trochanter</span> (palpation du massif)</td></tr>\n          <tr><td><strong>Impotence</strong></td><td>Appui possible (G1/2) ⇒ <span class=\"kw-alerte\">totale</span> (G3/4)</td><td><span class=\"kw-alerte\">Totale</span></td></tr>\n          <tr><td><strong>Déformation</strong></td><td>Raccourcissement + RE + adduction (si G3/4)</td><td><span class=\"kw-clinique\">Ascension du massif trochantérien</span></td></tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-info\">💡 <strong>Autonomie</strong> évaluée par le <span class=\"kw-def\">score de Parker</span> : 3 questions (marche intérieure, marche extérieure, courses), chacune cotée de <span class=\"kw-chiffre\">0</span> (non) à <span class=\"kw-chiffre\">3</span> (sans aide) ⇒ <span class=\"kw-chiffre\">/9</span>. Oriente le choix prothétique (<span class=\"kw-ttt\">PTH si ≥ 6</span>, <span class=\"kw-ttt\">PIH si &lt; 6</span>).</div>","frequence":2,"liens":[{"href":"https://www.passlassante.com/post/parker-proth%C3%A8se-de-hanche","label":"passlassante.com — Score de Parker"}]},{"id":"363-4","rang":"A","rubrique":"Examens complémentaires","titre":"Connaître l’indication, l’objectif et la sémiologie de base des examens d’imagerie devant une fracture de l’extrémité supérieure du fémur","contenu":"<p><strong>Indication</strong> : toute suspicion clinique de FESF. <strong>Objectif</strong> : confirmer la fracture, la <span class=\"kw-def\">localiser</span> (cervicale <span class=\"kw-bio\">vs</span> trochantérienne), évaluer le <span class=\"kw-def\">déplacement</span> (Garden) et le <span class=\"kw-def\">trait</span> (Pauwels, comminution).</p>\n\n      <h4 class=\"kw-def\">Incidences radiographiques de référence</h4>\n      <ul>\n        <li><span class=\"kw-imagerie\">Bassin de face</span> (vue d'ensemble, comparaison à la hanche saine).</li>\n        <li><span class=\"kw-imagerie\">Hanche de face</span>, membre en <span class=\"kw-chiffre\">rotation interne de 10°</span> : dégage une <strong>vraie face du col</strong> (anatomiquement antéversé de <span class=\"kw-chiffre\">10 à 20°</span>).</li>\n        <li><span class=\"kw-imagerie\">Profil chirurgical</span> (dit aussi <span class=\"kw-imagerie\">profil inguinal</span> ou <span class=\"kw-imagerie\">profil d'Arcelin</span>) : analyse le déplacement postérieur et la comminution.</li>\n      </ul>\n\n      <div class=\"callout callout-info\">💡 Repère anatomique : l'os trabéculaire du col forme des travées de résistance entrecroisées (<span class=\"kw-def\">éperon de Merkel</span>) — leur <span class=\"kw-alerte\">rupture</span> / désorientation signe la fracture sur la radio.</div>\n\n      <figure class=\"obj-figure\">\n        <img src=\"../assets/images/363/garden-col-femoral.png\" alt=\"Quatre radiographies de hanche droite de face illustrant la classification de Garden I à IV d'une fracture du col fémoral, avec schémas des travées osseuses\" loading=\"lazy\">\n        <figcaption>Radiographies de hanche droite de face (4 patients) — <span class=\"kw-imagerie\">Garden I</span> (incomplète, corticale médiale préservée, impaction en valgus) → <span class=\"kw-imagerie\">Garden IV</span> (complète, déplacement total, travées céphaliques et cervicales parallèles). Source : <em>Imagerie à connaître EDN</em>, item 363 (p. 89).</figcaption>\n      </figure>\n\n      <div class=\"callout callout-warn\">⚠️ Une fracture <span class=\"kw-imagerie\">Garden 1/2 engrenée non déplacée</span> peut être <span class=\"kw-alerte\">à peine visible</span> : en cas de forte suspicion clinique avec radio normale, compléter par <span class=\"kw-imagerie\">TDM</span> ou <span class=\"kw-imagerie\">IRM</span> (recherche de trait occulte).</div>","frequence":5,"liens":[{"href":"https://radiopaedia.org/cases/regions-of-the-proximal-femur-illustration","label":"Radiopaedia : Régions de l'extrémité proximale du fémur"}]},{"id":"363-5","rang":"A","rubrique":"Contenu multimédia","titre":"Radiographie de la hanche droite de face d’une fracture du col fémoral","contenu":"<p>Radiographies de <span class=\"kw-imagerie\">hanche droite de face</span> illustrant <span class=\"kw-clinique\">les</span> <strong>4 stades de Garden</strong> d'une fracture du col fémoral.</p>\n      <figure class=\"obj-figure\">\n        <img src=\"../assets/images/363/garden-col-femoral.png\" alt=\"Radiographies de hanche droite de face d'une fracture du col fémoral selon les 4 stades de Garden\" loading=\"lazy\">\n        <figcaption>Quatre patients distincts (RX hanche droite de face). Source : <em>Imagerie à connaître EDN</em>, item 363 (p. 89).</figcaption>\n      </figure>\n      <table >\n        <thead><tr><th><span class=\"kw-def\">Stade</span></th><th>Sémiologie radiographique</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Garden I</strong></td><td>Fracture <span class=\"kw-imagerie\">incomplète</span>, <span class=\"kw-imagerie\">corticale médiale préservée</span>, non déplacée, <span class=\"kw-imagerie\">impaction des travées céphaliques en valgus</span>.</td></tr>\n          <tr><td><strong>Garden II</strong></td><td>Fracture <span class=\"kw-imagerie\">complète, non déplacée</span> (travées parallèles).</td></tr>\n          <tr><td><strong>Garden III</strong></td><td>Fracture complète <span class=\"kw-imagerie\">déplacée</span> (déplacement partiel, <span class=\"kw-imagerie\">varisation des travées céphaliques</span> par rapport aux cervicales).</td></tr>\n          <tr><td><strong>Garden IV</strong></td><td>Fracture complète, <span class=\"kw-imagerie\">déplacement complet</span> : travées céphaliques et cervicales <span class=\"kw-imagerie\">redeviennent parallèles</span>.</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\">⚠️ Astuce de lecture : on suit l'orientation des <span class=\"kw-imagerie\">travées céphaliques</span>. Plus le déplacement augmente (Garden III → IV), plus le <span class=\"kw-alerte\">risque vasculaire et de nécrose</span> est élevé.</div>","frequence":2},{"id":"363-6","rang":"B","rubrique":"Examens complémentaires","titre":"Connaître la classification de Garden","contenu":"<p>La <span class=\"kw-def\">classification de Garden</span> décrit <span class=\"kw-clinique\">les</span> <strong>fractures du col fémoral</strong> selon leur <span class=\"kw-def\">déplacement</span> et l'analyse des <span class=\"kw-imagerie\">travées osseuses</span> sur la <span class=\"kw-imagerie\">radiographie de bassin de face</span>. Elle conditionne le <span class=\"kw-alerte\">risque de nécrose avasculaire</span> et la stratégie thérapeutique.</p>\n      <table >\n        <thead><tr><th>Type</th><th>Caractéristiques</th><th>Travées</th><th>Risque de <span class=\"kw-clinique\">nécrose</span></th></tr></thead>\n        <tbody>\n          <tr><td><strong>Garden I</strong></td><td>Impaction du col en <span class=\"kw-imagerie\">valgus</span> (engrenée, non déplacée)</td><td>Angle convexe en haut, <span class=\"kw-imagerie\">verticalisées</span></td><td><span class=\"kw-bio\">Faible</span></td></tr>\n          <tr><td><strong>Garden II</strong></td><td>Fracture <span class=\"kw-imagerie\">non déplacée</span>, engrènement du foyer</td><td><span class=\"kw-imagerie\">Parallèles</span></td><td><span class=\"kw-chiffre\">≈ 20 %</span></td></tr>\n          <tr><td><strong>Garden III</strong></td><td>Déplacée en <span class=\"kw-imagerie\">varus</span>, charnière interne conservée</td><td>Angle convexe en bas, <span class=\"kw-imagerie\">horizontalisées</span></td><td><span class=\"kw-chiffre\">≈ 50 %</span></td></tr>\n          <tr><td><strong>Garden IV</strong></td><td>Déplacée en <span class=\"kw-imagerie\">varus</span>, <span class=\"kw-alerte\">rupture complète de la capsule</span></td><td><span class=\"kw-imagerie\">Parallèles</span></td><td><span class=\"kw-chiffre\">≈ 70 %</span></td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\">💡 Repère : <strong>I-II = stables</strong> (souvent <span class=\"kw-ttt\">ostéosynthèse</span>) ; <strong>III-IV = instables</strong> (souvent <span class=\"kw-ttt\">arthroplastie</span> chez le sujet âgé).</div>\n\n      <h4 class=\"kw-def\"><span class=\"kw-clinique\">Les</span> autres classifications du col</h4>\n      <table >\n        <thead><tr><th><span class=\"kw-def\">Classification</span></th><th>Critère</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Delbet</strong></td><td>Localisation du trait : <span class=\"kw-imagerie\">sous-capital</span> · <span class=\"kw-imagerie\">trans-cervical</span> · <span class=\"kw-imagerie\">basi-cervical</span>.</td></tr>\n          <tr><td><strong>Pauwels</strong></td><td>Obliquité du trait (angle / horizontale) : <span class=\"kw-chiffre\">type 1 &lt; 30°</span> (compression, consolide) · <span class=\"kw-chiffre\">type 2 : 30-60°</span> · <span class=\"kw-chiffre\">type 3 &gt; 60°</span> (cisaillement, <span class=\"kw-alerte\">risque de pseudarthrose</span>).</td></tr>\n          <tr><td><strong>Mole et Ricard</strong></td><td>Comminution de la <span class=\"kw-imagerie\">corticale postérieure</span> (sur le profil) : trait simple = stable ; comminution = instable.</td></tr>\n        </tbody>\n      </table>","frequence":2,"liens":[{"href":"https://radiopaedia.org/articles/garden-classification-of-subcapital-femoral-neck-fractures","label":"Radiopaedia : Garden classification"}]},{"id":"363-7","rang":"B","rubrique":"Epidémiologie","titre":"Connaître les différents types de fracture du fémur proximal","contenu":"<p>On distingue selon le siège du trait par rapport à la <span class=\"kw-def\">ligne inter-trochantérienne</span> (= insertion capsulaire) :</p>\n      <table >\n        <thead><tr><th>Type</th><th>Situation &amp; particularités</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Fractures cervicales</strong><br>(intra-capsulaires)</td>\n            <td><span class=\"kw-def\">Os cortical</span>, <span class=\"kw-alerte\">vascularisation précaire</span> + forces de cisaillement ⇒ <strong>ne consolident pas</strong> après <span class=\"kw-ttt\">ostéosynthèse</span>, exposées à la <span class=\"kw-alerte\">nécrose</span> et à la <span class=\"kw-alerte\">pseudarthrose</span>.</td>\n          </tr>\n          <tr>\n            <td><strong>Fractures trochantériennes</strong><br>(extra-capsulaires)</td>\n            <td>Massif <span class=\"kw-bio\">richement vascularisé</span> ⇒ <strong>consolident</strong> après <span class=\"kw-ttt\">ostéosynthèse</span>. Sous-types selon le trait : <span class=\"kw-imagerie\">cervico-trochantérienne</span>, <span class=\"kw-imagerie\">per-trochantérienne</span>, <span class=\"kw-imagerie\">trochantéro-diaphysaire</span>, <span class=\"kw-imagerie\">sous-trochantérienne</span>.</td>\n          </tr>\n          <tr>\n            <td><strong>Fractures sous-trochantériennes</strong></td>\n            <td>Jonction métaphyso-diaphysaire <span class=\"kw-alerte\">mal vascularisée</span> + forte traction musculaire (déplacement difficile à réduire) ⇒ <span class=\"kw-alerte\">retard de consolidation / pseudarthrose</span>. <span class=\"kw-def\">Classification</span> de <span class=\"kw-def\">Seinsheimer</span>.</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4 class=\"kw-def\">Stabilité des fractures trochantériennes (Ender)</h4>\n      <ul>\n        <li><strong><span class=\"kw-bio\">Stables</span></strong> : basi-cervicale, per-trochantérienne simple → bonne stabilité après fixation.</li>\n        <li><strong><span class=\"kw-alerte\">Instables</span></strong> : inter-trochantérienne, per-trochantérienne complexe, sous-trochantérienne, trochantéro-diaphysaire.</li>\n        <li>Point commun des formes instables = <span class=\"kw-alerte\">détachement du petit trochanter</span> (= insertion de l'<span class=\"kw-def\">ilio-psoas</span>) ; <span class=\"kw-clinique\">les</span> formes à <span class=\"kw-chiffre\">4 fragments</span> sont les plus instables.</li>\n      </ul>","frequence":0,"liens":[{"href":"https://radiopaedia.org/articles/trochanteric-fracture","label":"Radiopaedia : Trochanteric fracture"}]},{"id":"363-8","rang":"A","rubrique":"Identifier une urgence","titre":"Comprendre l’urgence de la prise en charge des fractures du fémur proximal","contenu":"<div class=\"callout callout-danger\">🚩 Chez le <span class=\"kw-alerte\">sujet âgé</span>, un <strong>délai opératoire &gt; <span class=\"kw-chiffre\">48 h</span></strong> est le <span class=\"kw-alerte\">principal facteur de mortalité</span>. La <span class=\"kw-ttt\">chirurgie</span> n'a pas à être faite en pleine nuit, mais doit être réalisée <strong>dans <span class=\"kw-clinique\">les</span> <span class=\"kw-chiffre\">48 h</span></strong>.</div>\n      <p>L'<span class=\"kw-alerte\">urgence</span> n'est pas tant la fracture elle-même que la <span class=\"kw-alerte\">remise en charge précoce</span> : remettre le patient <strong>debout ou au fauteuil</strong> au plus vite pour limiter <span class=\"kw-clinique\">les</span> <span class=\"kw-alerte\">complications de décubitus</span> et la <span class=\"kw-alerte\">décompensation des comorbidités</span>.</p>\n      <table >\n        <thead><tr><th>Situation</th><th>Délai</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Jeune (&lt;<span class=\"kw-chiffre\"> 60 ans</span>) + fracture intracapsulaire déplacée du col</strong></td><td><span class=\"kw-alerte\">Urgence</span> : <span class=\"kw-ttt\">réduction</span> + ostéosynthèse <span class=\"kw-ttt\">au plus tôt</span> (sauver la tête fémorale).</td></tr>\n          <tr><td><strong>Jeune (&lt;<span class=\"kw-chiffre\"> 60 ans</span>) + fracture extracapsulaire</strong></td><td><span class=\"kw-ttt\">Urgence différée</span> (risque d'ostéonécrose faible).</td></tr>\n          <tr><td><strong>Sujet âgé</strong></td><td><span class=\"kw-ttt\">Chirurgie</span> <strong>dans <span class=\"kw-clinique\">les</span> <span class=\"kw-chiffre\">48 h</span></strong> ⇒ au-delà, <span class=\"kw-alerte\">surmortalité</span>.</td></tr>\n        </tbody>\n      </table>","frequence":1},{"id":"363-9","rang":"B","rubrique":"Prise en charge","titre":"Connaître le principe du traitement des fractures du fémur proximal","contenu":"<p>Deux logiques opposées selon l'entité : <strong>conserver la tête</strong> (<span class=\"kw-ttt\">ostéosynthèse</span>) <span class=\"kw-bio\">vs</span> <strong>la remplacer</strong> (arthroplastie). Le choix dépend de l'<span class=\"kw-clinique\">âge</span>, du <span class=\"kw-imagerie\">type/déplacement</span> et de l'<span class=\"kw-clinique\">autonomie</span> (<span class=\"kw-def\">score</span> de Parker).</p>\n\n      <h4 class=\"kw-def\">Fractures cervicales — indication selon Garden &amp; âge</h4>\n      <table >\n        <thead><tr><th><span class=\"kw-def\">Terrain</span></th><th>Garden 1/2</th><th>Garden 3/4</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Jeune (&lt;<span class=\"kw-chiffre\"> 50 ans</span>)</strong></td><td><span class=\"kw-ttt\">Ostéosynthèse</span></td><td><span class=\"kw-ttt\">Ostéosynthèse</span> (conserver la tête à tout prix)</td></tr>\n          <tr><td><strong><span class=\"kw-chiffre\">50-80 ans</span></strong></td><td><span class=\"kw-ttt\">Ostéosynthèse</span> (vissage)</td><td>Selon trait : vissage <span class=\"kw-bio\">vs</span> <span class=\"kw-ttt\">PTH</span> ; Pauwels 3 / Garden 4 → <span class=\"kw-ttt\">PTH</span></td></tr>\n          <tr><td><strong>Très âgé (&gt;<span class=\"kw-chiffre\"> 80 ans</span>) à FR</strong></td><td><span class=\"kw-ttt\">Arthroplastie</span></td><td><span class=\"kw-ttt\">Arthroplastie</span></td></tr>\n        </tbody>\n      </table>\n\n      <h4 class=\"kw-def\">Fractures trochantériennes</h4>\n      <ul>\n        <li><strong>Quasi-systématiquement</strong> : <span class=\"kw-ttt\">réduction</span> + <span class=\"kw-ttt\">ostéosynthèse</span> (le massif consolide bien).</li>\n        <li><span class=\"kw-ttt\">Clou gamma</span> si <span class=\"kw-ttt\">réduction</span> à <span class=\"kw-imagerie\">foyer fermé</span> ; <span class=\"kw-ttt\">vis-plaque / lame-plaque (DHS)</span> si foyer ouvert.</li>\n        <li>Prothèse seulement dans de rares cas (arthrose associée, fracture très instable).</li>\n      </ul>\n\n      <h4 class=\"kw-def\"><span class=\"kw-clinique\">Les</span> 3 types de prothèse</h4>\n      <table >\n        <thead><tr><th>Prothèse</th><th>Principe</th><th>Indication</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Céphalique (Moore)</strong></td><td>Remplace <span class=\"kw-imagerie\">la tête seule</span>, non cimentée</td><td>Quasi abandonnée (<span class=\"kw-alerte\">usure du cotyle</span>) — sujet âgé peu marchant</td></tr>\n          <tr><td><strong>Intermédiaire (PIH)</strong></td><td><span class=\"kw-imagerie\">Tête à double mobilité</span>, sans implant acétabulaire</td><td>Très âgé, faible autonomie (<span class=\"kw-chiffre\">Parker &lt; 6</span>)</td></tr>\n          <tr><td><strong>Totale (<span class=\"kw-bio\">PTH</span>)</strong></td><td><span class=\"kw-imagerie\">Pièce fémorale + implant acétabulaire</span> (cotyle prothésé)</td><td>Plus actif / arthrose associée (<span class=\"kw-chiffre\">Parker ≥ 6</span>) ; longévité <span class=\"kw-chiffre\">15-30 ans</span></td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\">💡 Différence radio PIH <span class=\"kw-bio\">vs</span> <span class=\"kw-bio\">PTH</span> : la <span class=\"kw-imagerie\">PIH</span> garde un <span class=\"kw-imagerie\">liseré</span> (interligne entre cupule mobile et cotyle non prothésé) ; la <span class=\"kw-imagerie\">PTH</span> n'a pas cet espace (cotyle fixé, souvent visualisé par des vis).</div>\n\n      <h4 class=\"kw-def\">Mesures associées (toutes FESF)</h4>\n      <ul>\n        <li><span class=\"kw-ttt\">Analgésie multimodale</span> (recours aux morphiniques), <span class=\"kw-ttt\">antibioprophylaxie</span> à l'induction.</li>\n        <li><strong>Prévention MTEV</strong> : mobilisation précoce + élastocontention + <span class=\"kw-ttt\">anticoagulation</span> (<span class=\"kw-ttt\">HBPM</span> / <span class=\"kw-ttt\">fondaparinux</span> / <span class=\"kw-ttt\">AOD</span>) pendant <span class=\"kw-chiffre\">5 semaines</span>.</li>\n        <li><span class=\"kw-ttt\">Rééducation</span> : mise au fauteuil et reprise d'appui précoces (<span class=\"kw-chiffre\">24-72 h</span>).</li>\n      </ul>","frequence":1,"liens":[{"href":"https://radiopaedia.org/articles/gamma-nail","label":"Radiopaedia : Gamma nail"},{"href":"https://radiologyassistant.nl/musculoskeletal/hip/arthroplasty","label":"radiologyassistant.nl — Arthroplastie de hanche"},{"href":"https://radiopaedia.org/articles/total-hip-arthroplasty","label":"Radiopaedia : Total hip arthroplasty"}]},{"id":"363-10","rang":"B","rubrique":"Suivi et/ou pronostic","titre":"Connaître les principales complications immédiates des fractures du fémur proximal et leur prévention","contenu":"<h4 class=\"kw-def\">Complications immédiates</h4>\n      <ul>\n        <li><span class=\"kw-alerte\">Complications vasculo-nerveuses</span> : <strong>exceptionnelles</strong> dans ce type de fracture, mais à rechercher systématiquement (<span class=\"kw-clinique\">pouls</span>, <span class=\"kw-clinique\">sensibilité</span>, <span class=\"kw-clinique\">motricité</span> distale).</li>\n        <li><span class=\"kw-alerte\">Lésion cutanée</span> : vérifier la couverture <span class=\"kw-ttt\">anti-tétanique</span>.</li>\n        <li><span class=\"kw-alerte\">Décompensation de tares préexistantes</span> (cardio-vasculaire, respiratoire, rénale, métabolique) favorisée par le décubitus et la douleur.</li>\n        <li><span class=\"kw-alerte\">Complications de décubitus</span>, débutant <strong>dès le 1ᵉʳ jour</strong> : <span class=\"kw-clinique\">thrombophlébite</span> / <span class=\"kw-alerte\">embolie pulmonaire</span>, <span class=\"kw-clinique\">infection respiratoire</span> et <span class=\"kw-clinique\">urinaire</span>, <span class=\"kw-clinique\">escarres</span>, <span class=\"kw-clinique\">dénutrition</span>, perte de la marche.</li>\n      </ul>\n      <div class=\"callout callout-warn\">⚠️ <strong>Les infections pulmonaires (pneumopathies)</strong> constituent la <span class=\"kw-alerte\">première cause de mortalité à J30</span> après fracture de l'ESF (mortalité à J30 ≈ <span class=\"kw-chiffre\">5–10 %</span>, jusqu'à <span class=\"kw-chiffre\">25 % à 1 an</span>). Elles justifient une <span class=\"kw-ttt\">kinésithérapie respiratoire</span> précoce et une <span class=\"kw-clinique\">verticalisation rapide</span>.</div>\n      <h4 class=\"kw-def\">Prévention</h4>\n      <ul>\n        <li><strong><span class=\"kw-ttt\">Chirurgie précoce</span></strong> (<span class=\"kw-chiffre\">≤ 48 h</span>) + <strong>remise debout / au fauteuil rapide</strong> = mesure clé contre le décubitus.</li>\n        <li><span class=\"kw-ttt\">Anticoagulation préventive</span> + élastocontention, <span class=\"kw-ttt\">nursing</span> (prévention escarres), kinésithérapie, prise en charge nutritionnelle.</li>\n      </ul>","frequence":1},{"id":"363-11","rang":"B","rubrique":"Suivi et/ou pronostic","titre":"Connaître les principales complications secondaires et tardives des fractures du fémur proximal","contenu":"<h4 class=\"kw-def\">Fractures cervicales</h4>\n      <ul>\n        <li><strong><span class=\"kw-alerte\">Pseudarthrose du col</span></strong> : absence de consolidation au-delà de <span class=\"kw-chiffre\">6 mois</span> (à distinguer du <span class=\"kw-def\">retard de consolidation</span> = consolidation à <span class=\"kw-chiffre\">2× le délai normal</span>, soit ~<span class=\"kw-chiffre\">3 mois</span>). FR : trait <span class=\"kw-imagerie\">vertical</span> (Pauwels 3), <span class=\"kw-ttt\">ostéosynthèse</span> insuffisamment stable. Traitement : <span class=\"kw-ttt\">PTH</span>, ou <span class=\"kw-ttt\">ostéotomie de valgisation</span> chez le jeune (horizontalise le trait).</li>\n        <li><strong><span class=\"kw-alerte\">Ostéonécrose de la tête fémorale</span></strong> : <span class=\"kw-clinique\">douleur diurne et nocturne</span> intense, à distance du traitement. <span class=\"kw-imagerie\">IRM</span> ou <span class=\"kw-imagerie\">scintigraphie</span> au <span class=\"kw-def\">stade</span> précoce (<span class=\"kw-imagerie\">IRM</span> <span class=\"kw-ci\">contre-indiquée si matériel métallique</span>), <span class=\"kw-imagerie\">radiographie</span> au stade d'effondrement sous-chondral. Traitement : <span class=\"kw-ttt\">PTH</span> quel que soit l'âge. <span class=\"kw-alerte\">Impossible après arthroplastie</span> (plus de tête fémorale).</li>\n      </ul>\n      <h4 class=\"kw-def\">Fractures trochantériennes</h4>\n      <ul>\n        <li><strong><span class=\"kw-alerte\">Cal vicieux</span></strong> : le plus souvent en <span class=\"kw-clinique\">varus</span>, <span class=\"kw-clinique\">raccourcissement</span> et <span class=\"kw-clinique\">rotation externe</span>. CAT : <span class=\"kw-ttt\">chaussure orthopédique</span> compensatrice (sujet âgé) ; chez le jeune, différer la remise en charge (prévention) puis <span class=\"kw-ttt\">ostéotomie de réorientation</span> si cal important.</li>\n        <li>L'<span class=\"kw-alerte\">ostéonécrose</span> est <strong>exceptionnelle</strong> ici (vascularisation riche).</li>\n      </ul>","frequence":2,"liens":[{"href":"https://radiopaedia.org/articles/osteonecrosis-of-the-femoral-head","label":"Radiopaedia : Ostéonécrose de la tête fémorale"},{"href":"https://radiopaedia.org/articles/fracture-non-union-1","label":"Radiopaedia : Pseudarthrose (non-union)"}]},{"id":"363-12","rang":"A","rubrique":"Prise en charge","titre":"Connaître les principes de la prise en charge des pathologies associées à la fracture proximale du fémur","contenu":"<p>La FESF du sujet âgé est rarement isolée : sa <span class=\"kw-alerte\">morbi-mortalité</span> tient surtout aux <span class=\"kw-etio\">comorbidités</span> et à leur <span class=\"kw-alerte\">décompensation</span> périopératoire.</p>\n      <h4 class=\"kw-def\">Évaluation &amp; prise en charge globale</h4>\n      <ul>\n        <li>Repérer et traiter la <span class=\"kw-alerte\">décompensation des tares</span> : <span class=\"kw-etio\">cardio-vasculaire</span>, <span class=\"kw-etio\">respiratoire</span>, <span class=\"kw-etio\">rénale</span>, <span class=\"kw-etio\">métabolique</span> (approche <span class=\"kw-clinique\">gériatrique</span> / ortho-gériatrie).</li>\n        <li>Évaluer le <span class=\"kw-clinique\">degré d'autonomie</span> (<span class=\"kw-def\">score</span> de Parker) et anticiper le <span class=\"kw-alerte\">risque de perte d'autonomie</span>.</li>\n        <li><strong><span class=\"kw-def\">Bilan préopératoire</span></strong> : <span class=\"kw-bio\">Groupe ABO-Rh (2 déterminations)</span>, <span class=\"kw-bio\">RAI</span>, <span class=\"kw-bio\">plaquettes</span>, <span class=\"kw-bio\">TP-TCA</span>, <span class=\"kw-bio\">NFS</span>, <span class=\"kw-bio\">ionogramme</span>, <span class=\"kw-bio\">urée-créatininémie</span>, <span class=\"kw-bio\">glycémie</span> ; consultation d'anesthésie (± <span class=\"kw-imagerie\">ECG</span>, <span class=\"kw-imagerie\">RXT</span>).</li>\n        <li>Si <span class=\"kw-clinique\">temps passé au sol &gt; 1 h</span> : rechercher une <span class=\"kw-alerte\">rhabdomyolyse</span> (<span class=\"kw-bio\">CPK</span>, <span class=\"kw-bio\">LDH</span>, <span class=\"kw-bio\">myoglobine</span>).</li>\n      </ul>\n      <h4 class=\"kw-def\">Prévention de la chute</h4>\n      <ul>\n        <li><span class=\"kw-ttt\">Activité physique adaptée</span> : renforcement musculaire, travail de l'équilibre.</li>\n        <li>Correction des <span class=\"kw-etio\">troubles visuels</span> (bilan ophtalmologique, adaptation des corrections) et <span class=\"kw-etio\">auditifs</span>.</li>\n        <li><span class=\"kw-def\">Aménagement du domicile</span> : suppression tapis/obstacles, éclairage, barres d'appui, sol antidérapant, aides techniques (canne, déambulateur).</li>\n        <li><span class=\"kw-def\">Révision de l'ordonnance</span> : arrêt ou réduction des médicaments à risque iatrogène de chute (psychotropes, hypotenseurs, hypoglycémiants).</li>\n        <li>Port de <span class=\"kw-ttt\">chaussures adaptées</span>, correction d'un trouble de la marche.</li>\n      </ul>\n      <h4 class=\"kw-def\">Prévention de la sarcopénie et de la dénutrition</h4>\n      <ul>\n        <li><span class=\"kw-ttt\">Apport protéique</span> suffisant : <span class=\"kw-chiffre\">1 à 1,2 g/kg/j</span>, avec supplémentation orale si besoin.</li>\n        <li><span class=\"kw-ttt\">Supplémentation en vitamine D</span> (± calcium) systématique chez le sujet âgé.</li>\n        <li><span class=\"kw-ttt\">Exercice physique régulier</span> (marche, renforcement musculaire) pour limiter la fonte musculaire.</li>\n      </ul>\n      <h4 class=\"kw-def\">Prévention de la récidive fracturaire (ostéoporose)</h4>\n      <ul>\n        <li>Prise en charge systématique de l'<span class=\"kw-etio\">ostéoporose</span> : bilan + <span class=\"kw-ttt\">traitement anti-ostéoporotique</span> ; <span class=\"kw-ttt\">éducation thérapeutique</span>.</li>\n      </ul>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 128 — Ostéopathie fragilisante · 108 — Troubles de la marche et de l'équilibre</em></p>","frequence":0},{"id":"363-13","rang":"B","rubrique":"Physiopathologie","titre":"Connaître les mécanismes lésionnels de l’extrémité inférieure du radius","contenu":"<p>Le mécanisme = une <span class=\"kw-etio\">chute sur la main</span>, dont l'orientation du poignet détermine le sens du déplacement (et donc le type lésionnel) :</p>\n      <table >\n        <thead><tr><th>Mécanisme</th><th>Déplacement</th><th>Comminution</th><th>Fractures types</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong><span class=\"kw-def\">Compression-extension</span></strong><br>(chute, poignet en hyperextension) — <span class=\"kw-chiffre\">≈ 95 %</span></td>\n            <td><span class=\"kw-imagerie\">Postérieur (dorsal)</span></td>\n            <td><span class=\"kw-imagerie\">Dorsale</span></td>\n            <td><span class=\"kw-def\">Pouteau-Colles</span>, <span class=\"kw-def\">Gérard-Marchant</span> (extra-art.) ; cunéenne externe (art.)</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-def\">Compression-flexion</span></strong><br>(chute, poignet en flexion, ou chute en arrière) — <span class=\"kw-chiffre\">≈ 5 %</span></td>\n            <td><span class=\"kw-imagerie\">Antérieur (palmaire)</span></td>\n            <td><span class=\"kw-imagerie\">Palmaire</span></td>\n            <td><span class=\"kw-def\">Goyrand-Smith</span> (extra-art.) ; marginale antérieure (art.)</td>\n          </tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\">💡 Règle d'énergie : plus le <span class=\"kw-alerte\">choc</span> est violent, plus la <span class=\"kw-imagerie\">comminution</span> est marquée ⇒ plus le foyer est <span class=\"kw-alerte\">instable</span>. <span class=\"kw-clinique\">Les</span> fractures <span class=\"kw-imagerie\">articulaires</span> (sujet jeune, haute énergie) sont plus difficiles à traiter que les <span class=\"kw-imagerie\">métaphysaires</span> (sujet âgé, basse énergie).</div>","frequence":0,"liens":[{"href":"https://radiopaedia.org/articles/distal-radial-fracture","label":"Radiopaedia : Distal radial fracture"},{"href":"https://radiologyassistant.nl/musculoskeletal/wrist/fractures","label":"radiologyassistant.nl — Fractures du poignet"}]},{"id":"363-14","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les modalités du diagnostic clinique d’une fracture de l’EIR","contenu":"<h4 class=\"kw-def\">Signes fonctionnels</h4>\n      <ul>\n        <li><span class=\"kw-clinique\">Craquement</span> audible lors du traumatisme.</li>\n        <li><span class=\"kw-alerte\">Impotence fonctionnelle totale</span> du poignet : le patient <span class=\"kw-clinique\">soutient son membre</span> traumatisé.</li>\n      </ul>\n      <h4 class=\"kw-def\">Inspection — déformations caractéristiques</h4>\n      <ul>\n        <li><span class=\"kw-clinique\">Œdème constant</span> ± <span class=\"kw-clinique\">ecchymose</span> (saignement fracturaire).</li>\n        <li><strong>De face</strong> : aspect en <span class=\"kw-imagerie\">main botte radiale</span> (toute fracture déplacée) = déformation en <span class=\"kw-imagerie\">« baïonnette »</span> par translation latérale du fragment épiphysaire + <span class=\"kw-imagerie\">saillie de la styloïde ulnaire</span>.</li>\n        <li><strong>De profil</strong> : <span class=\"kw-imagerie\">« dos de fourchette »</span> (compression-extension : Pouteau-Colles, Gérard-Marchant) <span class=\"kw-bio\">vs</span> <span class=\"kw-imagerie\">« ventre de fourchette »</span> (compression-flexion : Goyrand-Smith).</li>\n      </ul>\n      <h4 class=\"kw-def\">Palpation</h4>\n      <ul>\n        <li><span class=\"kw-def\">Signe de Laugier</span> : <span class=\"kw-imagerie\">horizontalisation de la ligne bi-styloïdienne</span>.</li>\n        <li>Fractures <strong>non déplacées</strong> : <span class=\"kw-clinique\">douleur exquise métaphysaire</span> qui oriente le diagnostic.</li>\n      </ul>","frequence":1},{"id":"363-15","rang":"A","rubrique":"Examens complémentaires","titre":"Connaître l’indication, l’objectif et la sémiologie de base des examens d’imagerie devant une fracture de l’extrémité inférieure du radius","contenu":"<h4 class=\"kw-def\">Examens</h4>\n      <ul>\n        <li><span class=\"kw-imagerie\">Radiographie du poignet</span> indispensable, <span class=\"kw-chiffre\">2 à 3 incidences</span> : <span class=\"kw-imagerie\">face</span>, <span class=\"kw-imagerie\">profil</span> ± <span class=\"kw-imagerie\">3/4</span> (si fracture articulaire).</li>\n        <li><span class=\"kw-imagerie\">TDM</span> en <span class=\"kw-bio\">complément</span> dans <span class=\"kw-clinique\">les</span> <span class=\"kw-imagerie\">fractures articulaires</span> (bilan des fragments).</li>\n      </ul>\n\n      <h4 class=\"kw-def\">Radio-anatomie normale (repères à vérifier)</h4>\n      <table >\n        <thead><tr><th>Repère</th><th><span class=\"kw-def\">Incidence</span></th><th>Norme</th><th>Si fracture (PC/GM)</th></tr></thead>\n        <tbody>\n          <tr><td>Angle d'inclinaison de la glène radiale</td><td>Face</td><td><span class=\"kw-chiffre\">≈ 25°</span> (regarde en bas, avant, dedans)</td><td><span class=\"kw-imagerie\">Horizontalisé</span></td></tr>\n          <tr><td>Ligne bi-styloïdienne</td><td>Face</td><td><span class=\"kw-chiffre\">≈ 15°</span></td><td><span class=\"kw-imagerie\">&lt; 15°</span> (horizontalisée)</td></tr>\n          <tr><td>Index radio-ulnaire distal</td><td>Face</td><td><span class=\"kw-chiffre\">≈ −2 mm</span> (ulna plus courte)</td><td><span class=\"kw-imagerie\">Nul ou positif</span></td></tr>\n          <tr><td>Antéversion de la glène (profil)</td><td>Profil</td><td><span class=\"kw-chiffre\">10-12°</span></td><td><span class=\"kw-imagerie\">Rétroversée</span> (PC/GM) · <span class=\"kw-imagerie\">exagérée</span> (Goyrand-Smith)</td></tr>\n        </tbody>\n      </table>\n\n      <h4 class=\"kw-def\"><span class=\"kw-alerte\"><span class=\"kw-def\">Critères de</span> gravité</span> / instabilité &amp; lésions associées</h4>\n      <ul>\n        <li><span class=\"kw-alerte\">Instabilité</span> : comminution dorsale importante, <span class=\"kw-imagerie\">fracture associée de l'ulna</span>, <span class=\"kw-chiffre\">âge &gt; 60 ans</span>, <span class=\"kw-imagerie\">bascule dorsale &gt; 20°</span>, atteinte articulaire.</li>\n        <li><strong>Lésions associées</strong> : <span class=\"kw-imagerie\">styloïde ulnaire</span> (= <span class=\"kw-def\">Gérard-Marchant</span>), <span class=\"kw-imagerie\">tête de l'ulna</span> / luxation radio-ulnaire distale, fracture du <span class=\"kw-imagerie\">scaphoïde</span>, <span class=\"kw-alerte\">lésion du ligament scapho-lunaire</span> (suspectée si cunéenne externe + <span class=\"kw-imagerie\">diastasis scapho-lunaire</span>).</li>\n      </ul>\n\n      <figure class=\"obj-figure\">\n        <img src=\"../assets/images/363/pouteau-colles-poignet.png\" alt=\"Radiographies de poignet gauche de face et de profil montrant une fracture de Pouteau-Colles de l'extrémité inférieure du radius avec déplacement dorsal\" loading=\"lazy\">\n        <figcaption>RX poignet (face + profil) : fracture de l'EIR <span class=\"kw-imagerie\">extra-articulaire</span>, <span class=\"kw-imagerie\">déplacement dorsal</span> du fragment distal, <span class=\"kw-imagerie\">horizontalisation de la ligne bistyloïdienne</span> (= Pouteau-Colles). Source : <em>Imagerie à connaître EDN</em>, item 363 (p. 90).</figcaption>\n      </figure>","frequence":1},{"id":"363-16","rang":"A","rubrique":"Contenu multimédia","titre":"Radiographie du poignet avec fracture de Pouteau-Colles","contenu":"<p>Radiographies de <span class=\"kw-imagerie\">poignet</span> (incidences de <span class=\"kw-imagerie\">face</span> et de <span class=\"kw-imagerie\">profil</span>) d'une fracture de <strong>Pouteau-Colles</strong>.</p>\n      <figure class=\"obj-figure\">\n        <img src=\"../assets/images/363/pouteau-colles-poignet.png\" alt=\"Radiographies de poignet gauche de face et de profil d'une fracture de Pouteau-Colles\" loading=\"lazy\">\n        <figcaption>Fracture de l'EIR : <span class=\"kw-imagerie\">extra-articulaire</span>, à <span class=\"kw-imagerie\">déplacement dorsal</span> du fragment distal, avec <span class=\"kw-imagerie\">horizontalisation de la ligne bistyloïdienne</span> (flèches). Source : <em>Imagerie à connaître EDN</em>, item 363 (p. 90).</figcaption>\n      </figure>\n      <table >\n        <thead><tr><th><span class=\"kw-def\">Incidence</span></th><th>Signes</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Face</strong></td><td>Déformation en <span class=\"kw-imagerie\">« baïonnette »</span> (translation latérale), <span class=\"kw-imagerie\">horizontalisation de la ligne bistyloïdienne</span> (&lt; 15°).</td></tr>\n          <tr><td><strong>Profil</strong></td><td>Déformation en <span class=\"kw-imagerie\">« dos de fourchette »</span> : <span class=\"kw-imagerie\">bascule postérieure</span> de l'épiphyse, surface articulaire <span class=\"kw-imagerie\">rétroversée</span>.</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\">💡 Le <strong>Pouteau-Colles</strong> est une fracture <span class=\"kw-imagerie\">extra-articulaire</span> à déplacement dorsal avec <span class=\"kw-imagerie\">styloïde ulnaire intacte</span> — c'est ce dernier point qui le distingue du <span class=\"kw-def\">Gérard-Marchant</span> (= PC + fracture de la styloïde ulnaire).</div>","frequence":2},{"id":"363-17","rang":"A","rubrique":"Identifier une urgence","titre":"Savoir rechercher les signes de gravité immédiate","contenu":"<div class=\"callout callout-danger\">🚩 Complications immédiates à rechercher systématiquement devant une fracture de l'EIR :\n        <ul>\n          <li><span class=\"kw-alerte\">Compression du nerf médian</span> : par l'<span class=\"kw-clinique\">hématome</span> dans le canal carpien ou par un <span class=\"kw-imagerie\">déplacement antérieur</span> (Goyrand-Smith ++).</li>\n          <li><span class=\"kw-alerte\">Incarcération du tendon du long extenseur du pouce</span> dans le foyer ⇒ <span class=\"kw-clinique\">perte de l'extension active de l'inter-phalangienne du pouce</span>.</li>\n          <li><span class=\"kw-alerte\">Ouverture cutanée</span> (fracture ouverte) ⇒ vérifier la <span class=\"kw-ttt\">vaccination anti-tétanique</span> (SAT-VAT).</li>\n          <li><span class=\"kw-alerte\">Atteinte vasculaire</span> : prise des <span class=\"kw-clinique\">pouls radial, ulnaire et axillaire</span>.</li>\n        </ul>\n      </div>\n      <div class=\"callout callout-warn\">⚠️ L'examen <span class=\"kw-clinique\">vasculo-nerveux</span> distal est <strong>obl<span class=\"kw-chiffre\">iga</span>toire avant et après <span class=\"kw-ttt\">réduction</span></strong> : noter sensibilité du territoire médian, mobilité du pouce, coloration et pouls.</div>","frequence":0},{"id":"363-18","rang":"B","rubrique":"Diagnostic positif","titre":"Connaître les formes cliniques des fractures de l’EIR","contenu":"<p><span class=\"kw-def\">Classification</span> de <span class=\"kw-def\">Castaing</span> : on oppose <span class=\"kw-clinique\">les</span> formes <span class=\"kw-imagerie\">extra-articulaires</span> (métaphysaires) et <span class=\"kw-imagerie\">articulaires</span> (épiphysaires), selon le sens du déplacement.</p>\n      <table >\n        <thead><tr><th></th><th>Déplacement postérieur (≈<span class=\"kw-chiffre\"> 95 %</span>)</th><th>Déplacement antérieur (≈<span class=\"kw-chiffre\"> 5 %</span>)</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Extra-articulaires</strong></td><td><span class=\"kw-def\">Pouteau-Colles</span>, <span class=\"kw-def\">Gérard-Marchant</span></td><td><span class=\"kw-def\">Goyrand-Smith</span></td></tr>\n          <tr><td><strong>Articulaires</strong></td><td>Cunéenne externe, refend en T, comminutive</td><td>Marginale antérieure / postérieure, comminutive</td></tr>\n          <tr><td><strong>Profil</strong></td><td><span class=\"kw-imagerie\">Dos de fourchette</span></td><td><span class=\"kw-imagerie\">Ventre de fourchette</span></td></tr>\n        </tbody>\n      </table>\n\n      <h4 class=\"kw-def\"><span class=\"kw-clinique\">Les</span> 3 formes extra-articulaires à connaître</h4>\n      <table >\n        <thead><tr><th>Forme</th><th>Mécanisme / déplacement</th><th>Spécificité</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Pouteau-Colles</strong></td>\n            <td>Compression-extension ; <span class=\"kw-imagerie\">déplacement dorsal</span> (3 éléments : bascule postérieure, ascension/raccourcissement, tassement latéral)</td>\n            <td><span class=\"kw-imagerie\">Styloïde ulnaire intacte</span> (≠ Gérard-Marchant)</td>\n          </tr>\n          <tr>\n            <td><strong>Gérard-Marchant</strong></td>\n            <td>= Pouteau-Colles <strong>+</strong> <span class=\"kw-imagerie\">fracture / arrachement de la styloïde ulnaire</span></td>\n            <td>Témoin d'un arrachement du <span class=\"kw-def\">ligament triangulaire</span> ; sans conséquence si pas d'instabilité radio-ulnaire</td>\n          </tr>\n          <tr>\n            <td><strong>Goyrand-Smith</strong></td>\n            <td>Compression-flexion (ou chute en arrière) ; <span class=\"kw-imagerie\">déplacement antérieur</span> (exagère l'antéversion de la glène), ventre de fourchette</td>\n            <td><span class=\"kw-alerte\">Risque de lésion du nerf médian</span> par le déplacement antérieur</td>\n          </tr>\n        </tbody>\n      </table>\n      <p>Formes <strong>articulaires</strong> (sujet jeune ++) : <span class=\"kw-imagerie\">cunéenne externe</span> (emporte la styloïde radiale, rechercher une <span class=\"kw-alerte\">lésion scapho-lunaire</span>), <span class=\"kw-imagerie\">marginales antérieure/postérieure</span>, et formes <span class=\"kw-imagerie\">complexes à 3 fragments</span> (postéro-médial, antéro-médial, latéral).</p>","frequence":0,"liens":[{"href":"https://radiopaedia.org/articles/colles-fracture","label":"Radiopaedia : Colles fracture"},{"href":"https://radiopaedia.org/articles/smith-fracture","label":"Radiopaedia : Smith (Goyrand) fracture"}]},{"id":"363-19","rang":"B","rubrique":"Suivi et/ou pronostic","titre":"Connaître les principales complications immédiates, secondaires et tardives des fractures de l’extrémité inférieure du radius","contenu":"<div class=\"callout callout-info\">💡 <strong>Facteurs de mauvais <span class=\"kw-def\">pronostic</span></strong> : <span class=\"kw-etio\">âge élevé</span>, <span class=\"kw-etio\">ostéoporose</span>, <span class=\"kw-etio\">polytraumatisme</span> ; localement <span class=\"kw-imagerie\">comminution importante</span>, <span class=\"kw-imagerie\">nombre de fragments élevé</span>, <span class=\"kw-imagerie\">trait articulaire</span> (arthrose), <span class=\"kw-imagerie\">instabilité radio-ulnaire distale</span>, <span class=\"kw-alerte\">ouverture cutanée</span>.</div>\n\n      <table >\n        <thead><tr><th>Phase</th><th>Complications</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Immédiates</strong></td>\n            <td><span class=\"kw-alerte\">Compression du nerf médian</span> · incarcération du <span class=\"kw-clinique\">long extenseur du pouce</span> · <span class=\"kw-alerte\">ouverture cutanée</span> · atteinte vasculaire (cf. objectif <span class=\"kw-alerte\">urgence</span>).</td>\n          </tr>\n          <tr>\n            <td><strong>Secondaires</strong></td>\n            <td><span class=\"kw-alerte\">Syndrome des loges</span> (rare mais grave, loge palmaire de l'avant-bras/main) · <span class=\"kw-alerte\">déplacement secondaire sous plâtre</span> (surtout <span class=\"kw-clinique\">les</span> <span class=\"kw-chiffre\">3 premières semaines</span>) · <span class=\"kw-clinique\">enraidissement des doigts</span> (<span class=\"kw-clinique\">œdème</span>, surtout MCP) · <span class=\"kw-alerte\">syndrome du canal carpien</span> (possible même sans déplacement).</td>\n          </tr>\n          <tr>\n            <td><strong>Tardives</strong></td>\n            <td><span class=\"kw-alerte\">SDRC type 1 (algodystrophie)</span> — prévention par <span class=\"kw-ttt\">vitamine C</span> dès le jour de la fracture, pendant <span class=\"kw-chiffre\">1,5 mois</span> · <span class=\"kw-alerte\">cal vicieux</span> (<span class=\"kw-ttt\">réduction</span> insuffisante / déplacement secondaire) · <span class=\"kw-alerte\">arthrose</span> post-traumatique (corrélée à la qualité de réduction des formes articulaires).</td>\n          </tr>\n        </tbody>\n      </table>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 365 — <span class=\"kw-def\">Surveillance</span> d'un malade sous plâtre</em></p>","frequence":3},{"id":"363-20","rang":"B","rubrique":"Prise en charge","titre":"Connaître les principes du traitement des fractures de l’extrémité inférieure du radius","contenu":"<p>Logique en deux temps : <strong>réduire</strong> <span class=\"kw-clinique\">les</span> fractures déplacées, puis <strong>stabiliser</strong> selon la stabilité obtenue. Éléments décisionnels : <span class=\"kw-clinique\">âge</span>, <span class=\"kw-clinique\">demande fonctionnelle</span>, type (articulaire ou non), réductibilité, comminution, ostéoporose.</p>\n\n      <h4 class=\"kw-def\">1 · <span class=\"kw-ttt\">Réduction</span> (fractures déplacées)</h4>\n      <ul>\n        <li>Sous <span class=\"kw-ttt\">anesthésie loco-régionale</span> (parfois générale), contrôle scopique.</li>\n        <li>Constante : <span class=\"kw-clinique\">traction forte et prolongée</span> dans l'axe des <span class=\"kw-clinique\">2ᵉ-3ᵉ doigts</span>, puis selon le déplacement :\n          <ul>\n            <li><strong>Postérieur</strong> → <span class=\"kw-clinique\">inclinaison ulnaire + flexion palmaire</span>.</li>\n            <li><strong>Antérieur</strong> → <span class=\"kw-clinique\">inclinaison ulnaire + extension dorsale</span>.</li>\n          </ul>\n        </li>\n        <li><strong>4 <span class=\"kw-def\">critères de</span> <span class=\"kw-ttt\">réduction</span></strong> à vérifier : <span class=\"kw-imagerie\">ligne bi-styloïdienne</span>, <span class=\"kw-imagerie\">index radio-ulnaire</span>, <span class=\"kw-imagerie\">orientation de la glène</span>, <span class=\"kw-imagerie\">alignement des corticales</span> (corrélation étroite réduction ↔ résultat fonctionnel).</li>\n      </ul>\n\n      <h4 class=\"kw-def\">2 · Stabilisation</h4>\n      <table >\n        <thead><tr><th>Si <span class=\"kw-ttt\">réduction</span> stable</th><th>Si réduction instable</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong><span class=\"kw-ttt\">Traitement orthopédique</span></strong> : <span class=\"kw-ttt\">manchette plâtrée/résine</span> pendant <span class=\"kw-chiffre\">6 semaines</span> (plâtre brachio-antébrachio-palmaire si stabilisation du coude nécessaire).</td>\n            <td><strong><span class=\"kw-ttt\">Traitement chirurgical</span></strong> (méthodes associables) : <span class=\"kw-ttt\">embrochage de Kapandji</span>, <span class=\"kw-ttt\">plaque antérieure vissée</span> (méthode de choix), <span class=\"kw-clinique\">plaque</span> dorsale (<span class=\"kw-alerte\">plus de complications</span>), <span class=\"kw-ttt\">fixateur externe</span> — <span class=\"kw-ci\">jamais utilisé seul</span> (risque d'algodystrophie).</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4 class=\"kw-def\">3 · <span class=\"kw-def\">Surveillance</span> &amp; consolidation</h4>\n      <ul>\n        <li><strong>Orthopédique</strong> : RX à <span class=\"kw-chiffre\">J2, J8, J15, J21</span> (1×/sem × 3 sem) puis <span class=\"kw-chiffre\">J45</span> — dépister le déplacement secondaire.</li>\n        <li><strong>Chirurgical</strong> : RX à <span class=\"kw-chiffre\">J15</span> et <span class=\"kw-chiffre\">J45</span> ; ablation éventuelle des broches à J45 (<span class=\"kw-clinique\">les</span> plaques sont laissées en place).</li>\n        <li><strong>Consolidation</strong> habituelle : <span class=\"kw-chiffre\">6 semaines</span>.</li>\n      </ul>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 365 — <span class=\"kw-def\">Surveillance</span> d'un malade sous plâtre</em></p>","frequence":0}],"astuces":[],"strategie":{"urgence":"<p><strong>FESF — délai :</strong> geste opératoire dans <span class=\"kw-clinique\">les</span> <span class=\"kw-chiffre\">48h</span> ; chez le sujet âgé, un <span class=\"kw-alerte\">délai opératoire > 48h est le principal facteur de mortalité</span>.<br><strong>Col déplacé du sujet jeune :</strong> <span class=\"kw-ttt\">réduction + ostéosynthèse au plus tôt</span> pour <span class=\"kw-ttt\">conserver la tête fémorale</span> (risque d'<span class=\"kw-etio\">ostéonécrose</span>).<br><strong>1er geste :</strong> <span class=\"kw-ttt\">antalgie multimodale</span> (recours aux <span class=\"kw-ttt\">morphiniques</span>), <span class=\"kw-ttt\">mise en traction d'attente</span> et <span class=\"kw-ttt\">immobilisation</span>.<br><strong>FEIR :</strong> <span class=\"kw-ttt\">réduction</span> de toute fracture <span class=\"kw-clinique\">déplacée</span>, <span class=\"kw-ttt\">immobilisation par attelle</span> et <span class=\"kw-ttt\">antalgie</span>.</p>","hospit":"<p><strong>FESF :</strong> <span class=\"kw-ttt\">hospitalisation en chirurgie orthopédique en urgence</span> — <span class=\"kw-ttt\">mise à jeun</span>, <span class=\"kw-ttt\">consultation d'anesthésie</span> et <span class=\"kw-def\">bilan pré-opératoire</span> (<span class=\"kw-bio\">ABO-Rh 2 déterminations, RAI, TP-TCA, plaquettes</span>).<br><strong>FEIR :</strong> <span class=\"kw-ttt\">immobilisation par attelle amovible</span>, avis orthopédiste ; prise en charge réglée (ambulatoire ou <span class=\"kw-ttt\">chirurgie</span> programmée selon la stabilité après <span class=\"kw-ttt\">réduction</span>).</p>","redflags":"<ul><li>FESF — <span class=\"kw-alerte\">complications vasculaires et nerveuses</span> à rechercher (pouls, sensibilité, motricité), exceptionnelles dans ce type de fracture</li><li>FESF — <span class=\"kw-alerte\">rhabdomyolyse</span> si <span class=\"kw-chiffre\">temps passé au sol > 1 heure</span> : doser <span class=\"kw-bio\">CPK</span>, <span class=\"kw-bio\">LDH</span>, <span class=\"kw-bio\">myoglobine</span></li><li>FEIR — <span class=\"kw-alerte\">incarcération du tendon long extenseur du pouce</span> : <span class=\"kw-clinique\">perte de l'extension active de l'inter-phalangienne du pouce</span></li><li>FEIR — <span class=\"kw-alerte\">compression du nerf médian</span> (hématome du canal carpien ou déplacement antérieur)</li><li>FEIR — atteinte <span class=\"kw-alerte\">vasculaire</span> : prise des <span class=\"kw-clinique\">pouls radial, ulnaire et axillaire</span></li><li><span class=\"kw-alerte\">Ouverture cutanée</span> (fracture ouverte) : vérifier la <span class=\"kw-ttt\">couverture vaccinale antitétanique</span></li><li>FEIR instable — critères : <span class=\"kw-radio\">comminution dorsale</span>, <span class=\"kw-etio\">fracture associée de l'ulna</span>, <span class=\"kw-chiffre\">âge > 60 ans</span>, <span class=\"kw-radio\">bascule dorsale > 20°</span>, <span class=\"kw-radio\">atteinte articulaire</span></li></ul>","principes":"<p>Le choix thérapeutique dépend du <span class=\"kw-def\">siège</span> (col <span class=\"kw-bio\">vs</span> trochanter), du <span class=\"kw-radio\">déplacement (classification de Garden)</span>, de l'<span class=\"kw-def\">âge</span> et de l'<span class=\"kw-def\">autonomie (score de Parker)</span>.</p><p><strong>FESF cervicale (col fémoral)</strong></p><p>Risque d'<span class=\"kw-etio\">ostéonécrose</span> croissant avec le déplacement (≈ <span class=\"kw-chiffre\">20%</span> en Garden 2, <span class=\"kw-chiffre\">70%</span> en Garden 4)</p><ul><li>Sujet jeune < 50 ans : <span class=\"kw-ttt\"><span class=\"kw-ttt\">ostéosynthèse</span></span> pour <span class=\"kw-ttt\">conserver la tête fémorale</span>, quel que soit le Garden</li><li><span class=\"kw-chiffre\">50-80 ans</span>, <span class=\"kw-radio\">Garden 1-2 (non déplacée)</span> : <span class=\"kw-ttt\">ostéosynthèse par vissage</span></li><li><span class=\"kw-radio\">Garden 3-4 déplacée</span> ou sujet <span class=\"kw-chiffre\">> 80 ans</span> : <span class=\"kw-ttt\">arthroplastie</span> — <span class=\"kw-ttt\">PTH</span> si <span class=\"kw-chiffre\">Parker ≥ 6</span>, <span class=\"kw-ttt\">PIH</span> si <span class=\"kw-chiffre\">Parker < 6</span></li></ul><p><strong>FESF trochantérienne</strong></p><ul><li><span class=\"kw-ttt\">Réduction + ostéosynthèse</span> dans pratiquement tous les cas (massif <span class=\"kw-def\">richement vascularisé</span>)</li><li><span class=\"kw-ttt\">Clou gamma</span> si réduction à foyer fermé ; <span class=\"kw-ttt\">vis-plaque / lame-plaque</span> si foyer ouvert</li><li><span class=\"kw-ttt\">Prothèse</span> dans de rares cas (arthrose associée ou fracture particulièrement instable)</li></ul><p><strong>FEIR (radius distal)</strong></p><p>Réduction : <span class=\"kw-ttt\">traction forte du 2e-3e doigt</span> puis déplacement postérieur → <span class=\"kw-ttt\">inclinaison ulnaire + flexion palmaire</span> ; antérieur → <span class=\"kw-ttt\">inclinaison ulnaire + extension dorsale</span></p><ul><li><span class=\"kw-ttt\">Orthopédique</span> (<span class=\"kw-ttt\">manchette plâtre/résine</span> <span class=\"kw-chiffre\">6 semaines</span>) : fracture non déplacée, déplacée stable après réduction, ou sujet très âgé à faible demande fonctionnelle</li><li><span class=\"kw-ttt\">Chirurgical</span> si déplacée et instable après réduction : <span class=\"kw-ttt\">embrochage de Kapandji</span>, <span class=\"kw-ttt\">plaque antérieure vissée</span></li><li><span class=\"kw-ttt\">Fixateur externe</span> : <span class=\"kw-ci\">à ne jamais utiliser seul</span> (traction excessive → algodystrophie)</li></ul><p><strong>Mesures associées (FESF)</strong></p><ul><li><span class=\"kw-ttt\">Antibioprophylaxie</span> à l'induction anesthésique (prévention infection du site opératoire)</li><li>Prévention <span class=\"kw-alerte\">MTEV</span> : <span class=\"kw-ttt\">HBPM / fondaparinux / AOD</span> pendant <span class=\"kw-chiffre\">5 semaines</span> + mobilisation précoce et élastocontention</li><li><span class=\"kw-ttt\">Rééducation</span> : mise au fauteuil et reprise d'appui précoces (<span class=\"kw-chiffre\">24-72h</span>) contre les complications de décubitus</li><li>Prévention de la récidive : prise en charge d'une <span class=\"kw-etio\">ostéoporose</span></li></ul>","suivi":"<p><strong>FEIR orthopédique :</strong> <span class=\"kw-def\">surveillance</span> clinique et <span class=\"kw-imagerie\">radiographique</span> à <span class=\"kw-chiffre\">J2, J8, J15, J21, J45</span> (1×/semaine <span class=\"kw-chiffre\">3 semaines</span> puis 6e semaine) — guetter le <span class=\"kw-alerte\">déplacement secondaire sous plâtre</span> (3 premières semaines).<br><strong>FEIR chirurgical :</strong> <span class=\"kw-imagerie\">RX</span> de contrôle à <span class=\"kw-chiffre\">J15</span> et <span class=\"kw-chiffre\">J45</span> (ablation éventuelle des broches) ; consolidation en <span class=\"kw-chiffre\">6 semaines</span>.<br><strong>Prévention algodystrophie (SDRC type 1) :</strong> <span class=\"kw-ttt\">vitamine C</span> dès le jour de la fracture, pendant <span class=\"kw-chiffre\">1,5 mois</span>.<br><strong>FESF :</strong> surveillance des <span class=\"kw-alerte\">complications de décubitus</span>, <span class=\"kw-ttt\">anticoagulation</span> <span class=\"kw-chiffre\">5 semaines</span>, <span class=\"kw-def\">dépistage</span> et traitement de l'<span class=\"kw-etio\">ostéoporose</span>.</p>"},"liensGlobaux":[{"href":"https://radiopaedia.org/articles/distal-radial-fracture","label":"radiopaedia.org"},{"href":"https://radiologyassistant.nl/musculoskeletal/wrist/fractures","label":"radiologyassistant.nl"},{"href":"https://radiopaedia.org/articles/colles-fracture","label":"radiopaedia.org"},{"href":"https://radiopaedia.org/articles/smith-fracture","label":"radiopaedia.org"},{"href":"https://radiopaedia.org/articles/proximal-femoral-fractures","label":"radiopaedia.org"},{"href":"https://radiopaedia.org/cases/regions-of-the-proximal-femur-illustration","label":"radiopaedia.org"},{"href":"https://radiopaedia.org/cases/femoral-head-blood-supply","label":"radiopaedia.org"},{"href":"https://www.passlassante.com/post/parker-proth%C3%A8se-de-hanche","label":"passlassante.com"},{"href":"https://info-radiologie.ch/radiographie_bassin.php","label":"info-radiologie.ch"},{"href":"https://radiopaedia.org/cases/normal-pelvic-radiograph","label":"radiopaedia.org"},{"href":"https://radiopaedia.org/articles/garden-classification-of-subcapital-femoral-neck-fractures","label":"radiopaedia.org"},{"href":"https://radiopaedia.org/articles/trochanteric-fracture","label":"radiopaedia.org"},{"href":"https://radiologyassistant.nl/musculoskeletal/hip/arthroplasty","label":"radiologyassistant.nl"},{"href":"https://www.orthopedie-savoie.fr/upload/Les-pathologies/la-hanche/protheses-totales-de-hanche.pdf","label":"orthopedie-savoie.fr"},{"href":"https://www.genouhanche.fr/fr/hanche/pth-a-double-mobilite-une-revolution-francaise.html","label":"genouhanche.fr"},{"href":"https://www.canva.com/design/DAGfqSC6gfM/7D3N_ab_DNaZqGZVCy32Hg/view","label":"canva.com"},{"href":"https://radiopaedia.org/articles/hip-hemiarthroplasty","label":"radiopaedia.org"},{"href":"https://radiopaedia.org/articles/total-hip-arthroplasty","label":"radiopaedia.org"},{"href":"https://radiopaedia.org/articles/gamma-nail","label":"radiopaedia.org"},{"href":"https://radiopaedia.org/articles/fracture-non-union-1","label":"radiopaedia.org"},{"href":"https://radiopaedia.org/articles/osteonecrosis-of-the-femoral-head","label":"radiopaedia.org"},{"href":"https://radiopaedia.org/articles/fracture-healing","label":"radiopaedia.org"}],"arbre":{"rootId":"root","nodes":[{"id":"root","kind":"root","label":"Fracture fréquente — quel siège ? — Extrémité supérieure du fémur (FESF) vs extrémité inférieure du radius (FEIR)","detail":"<h4>CAT — Fractures fréquentes (fémur proximal & radius distal) — Orientation thérapeutique selon le siège, le déplacement, l'âge et l'autonomie</h4>","branches":[{"to":"q-fesf-siege","label":"Fémur proximal (hanche)","color":"blue"},{"to":"q-feir-deplace","label":"Radius distal (poignet)","color":"blue"}]},{"id":"q-fesf-siege","kind":"decision","label":"Siège du trait fémoral ? — Col (intra-capsulaire) vs trochanter (extra-capsulaire)","branches":[{"to":"t-osteo-troch","label":"Trochantérienne","color":"amber"},{"to":"q-fesf-garden","label":"Cervicale (col)","color":"blue"}]},{"id":"t-osteo-troch","kind":"terminal","label":"Ostéosynthèse (clou gamma) — Fracture trochantérienne (extra-capsulaire)","color":"amber","detail":"<h4>Traitement</h4><ul><li><span class=\"kw-ttt\">Réduction + ostéosynthèse</span> dans pratiquement tous <span class=\"kw-clinique\">les</span> cas</li><li><span class=\"kw-ttt\">Clou gamma</span> (foyer fermé) ou <span class=\"kw-ttt\">vis-plaque / lame-plaque</span> (foyer ouvert)</li></ul><h4>Conduite</h4><ul><li>Massif <span class=\"kw-def\">richement vascularisé</span> → consolide après <span class=\"kw-ttt\">ostéosynthèse</span>, <span class=\"kw-etio\">ostéonécrose exceptionnelle</span></li></ul>"},{"id":"q-fesf-garden","kind":"decision","label":"Terrain et déplacement (Garden) ? — Âge du patient et déplacement de la fracture cervicale","branches":[{"to":"t-osteo-col","label":"Sujet jeune < 50 ans","color":"red"},{"to":"t-vissage","label":"50-80 ans · Garden 1-2","color":"amber"},{"to":"q-parker","label":"Garden 3-4 déplacée / > 80 ans","color":"blue"}]},{"id":"t-osteo-col","kind":"terminal","label":"<span class=\"kw-ttt\">Ostéosynthèse</span> — conservation de la tête — Col fémoral, sujet jeune < <span class=\"kw-chiffre\"<span class=\"kw-chiffre\">>50</span> ans</span>","color":"red","detail":"<h4>Délai</h4><ul><li><span class=\"kw-alerte\">Urgence</span> si <span class=\"kw-radio\">Garden 3-4 déplacée</span> : <span class=\"kw-ttt\">réduction + ostéosynthèse au plus tôt</span></li></ul><h4>Traitement</h4><ul><li><span class=\"kw-ttt\">Ostéosynthèse</span> pour <span class=\"kw-ttt\">conserver la tête fémorale</span> par tous <span class=\"kw-clinique\">les</span> moyens</li></ul><h4><span class=\"kw-def\">Surveillance</span></h4><ul><li>Risque secondaire d'<span class=\"kw-etio\">ostéonécrose</span> et de <span class=\"kw-etio\">pseudarthrose</span></li></ul>"},{"id":"t-vissage","kind":"terminal","label":"Ostéosynthèse par vissage — Col, 50-80 ans, Garden 1-2 (non déplacée)","color":"amber","detail":"<h4>Traitement</h4><ul><li><span class=\"kw-ttt\">Vissage</span> (triple vissage ou vis-<span class=\"kw-clinique\">plaque</span>)</li></ul><h4>Conduite</h4><ul><li>Fracture <span class=\"kw-radio\">non déplacée / engrenée</span> → risque vasculaire faible</li></ul>"},{"id":"q-parker","kind":"decision","label":"Autonomie — score de Parker ? — Choix du type d'arthroplastie","branches":[{"to":"t-pth","label":"Parker ≥ 6","color":"amber"},{"to":"t-pih","label":"Parker < 6","color":"amber"}]},{"id":"t-pth","kind":"terminal","label":"Prothèse totale de hanche (PTH) — Col déplacé / sujet âgé autonome","color":"amber","detail":"<h4>Conduite</h4><ul><li>Indiquée si <span class=\"kw-chiffre\">score de Parker ≥ 6</span> (patient autonome)</li></ul><h4>Traitement</h4><ul><li>Remplacement <span class=\"kw-ttt\">tête fémorale + cotyle</span> ; modèle <span class=\"kw-ttt\">double mobilité</span> souvent utilisé</li></ul>"},{"id":"t-pih","kind":"terminal","label":"Prothèse intermédiaire (PIH) — Col déplacé / sujet très âgé peu autonome","color":"amber","detail":"<h4>Conduite</h4><ul><li>Indiquée si <span class=\"kw-chiffre\">score de Parker < 6</span> (faible autonomie)</li></ul><h4>Traitement</h4><ul><li><span class=\"kw-ttt\">Tête à double glissement</span>, sans implant acétabulaire</li></ul>"},{"id":"q-feir-deplace","kind":"decision","label":"Fracture du radius déplacée ?","branches":[{"to":"t-ortho-radius","label":"Non déplacée","color":"green"},{"to":"q-feir-stable","label":"Déplacée → réduction","color":"blue"}]},{"id":"t-ortho-radius","kind":"terminal","label":"Traitement orthopédique — FEIR non déplacée ou stable après réduction","color":"green","detail":"<h4>Traitement</h4><ul><li><span class=\"kw-ttt\">Manchette plâtre / résine</span> pendant <span class=\"kw-chiffre\">6 semaines</span></li><li>Aussi chez le sujet très âgé à <span class=\"kw-def\">faible demande fonctionnelle</span> (même si instable)</li></ul><h4><span class=\"kw-def\">Surveillance</span></h4><ul><li><span class=\"kw-imagerie\">RX</span> à <span class=\"kw-chiffre\">J2, J8, J15, J21, J45</span> — guetter le <span class=\"kw-alerte\">déplacement secondaire sous plâtre</span></li></ul>"},{"id":"q-feir-stable","kind":"decision","label":"Stable après réduction ? — Réduction de toute fracture déplacée puis test de stabilité","branches":[{"to":"t-ortho-radius","label":"Stable (ou âgé, demande faible)","color":"green"},{"to":"t-chir-radius","label":"Instable après réduction","color":"amber"}]},{"id":"t-chir-radius","kind":"terminal","label":"Chirurgie (ostéosynthèse) — FEIR déplacée et instable après réduction","color":"amber","detail":"<h4>Traitement</h4><ul><li><span class=\"kw-ttt\">Embrochage de Kapandji</span> ou <span class=\"kw-ttt\">plaque antérieure vissée</span></li><li><span class=\"kw-ttt\">Fixateur externe</span> : <span class=\"kw-ci\">jamais utilisé seul</span> (risque d'algodystrophie)</li></ul><h4><span class=\"kw-def\">Surveillance</span></h4><ul><li><span class=\"kw-imagerie\">RX</span> à <span class=\"kw-chiffre\">J15</span> et <span class=\"kw-chiffre\">J45</span> ; ablation des broches à J45</li></ul>"}]},"cards":[{"i":"22f3cb719794","n":363,"o":"363-12","u":"Prise en charge","t":"Connaître les principes de la prise en charge des pathologies associées à la fracture proximale du fémur","q":"Quelle est la principale source de morbi-mortalité pour une fracture de l'extrémité supérieure du fémur (FESF) chez le sujet âgé ?","a":"<p>La morbi-mortalité de la FESF chez le sujet âgé est principalement due aux <strong>comorbidités</strong> et à leur <strong>décompensation périopératoire</strong>, plutôt qu'à la fracture elle-même qui est rarement isolée.</p>"},{"i":"8e3aaeacbee9","n":363,"o":"363-12","u":"Prise en charge","t":"Connaître les principes de la prise en charge des pathologies associées à la fracture proximale du fémur","q":"Comment prévenir la récidive d'une fracture de l'extrémité supérieure du fémur (FESF) ?","a":"<p>La prévention de la récidive repose sur :</p><ul><li>La prise en charge systématique de l'<strong>ostéoporose</strong> (bilan et traitement anti-ostéoporotique).</li><li>L'<strong>éducation thérapeutique</strong>, notamment sur la prévention des chutes.</li></ul>"},{"i":"9da19ee50a8d","n":363,"o":"363-12","u":"Prise en charge","t":"Connaître les principes de la prise en charge des pathologies associées à la fracture proximale du fémur","q":"Quelles sont les tares à repérer et traiter en priorité lors de la prise en charge d'une FESF chez le sujet âgé ?","a":"<p>Il est crucial de repérer et prendre en charge la décompensation des tares suivantes :</p><ul><li><strong>Cardio-vasculaires</strong></li><li><strong>Respiratoires</strong></li><li><strong>Rénales</strong></li><li><strong>Métaboliques</strong></ul><p>Ceci s'inscrit dans une approche gériatrique ou ortho-gériatrique.</p>"},{"i":"fbbe9df3be8d","n":363,"o":"363-12","u":"Prise en charge","t":"Connaître les principes de la prise en charge des pathologies associées à la fracture proximale du fémur","q":"Quel est le bilan préopératoire minimal à réaliser pour une fracture de l'extrémité supérieure du fémur (FESF) et quel est l'examen à envisager en cas de temps passé au sol prolongé ?","a":"<p>Le bilan préopératoire minimal comprend :</p><ul><li><strong> Groupe ABO-Rh (2 déterminations), RAI</strong></li><li><strong> NFS, plaquettes</strong></li><li><strong> TP-TCA</strong></li><li><strong> Ionogramme, urée-créatininémie, glycémie</strong></li><li><strong> Consultation d'anesthésie (avec potentiellement ECG, RXT)</strong></li></ul><p>Si le temps passé au sol est <strong>supérieur à 1 heure</strong>, il faut rechercher une rhabdomyolyse en dosant les <strong>CPK, LDH, et la myoglobine</strong>.</p>"},{"i":"b02edf5183df","n":363,"o":"363-14","u":"Diagnostic positif","t":"Connaître les modalités du diagnostic clinique d’une fracture de l’EIR","q":"Quelles sont les déformations caractéristiques observées à l'inspection lors d'une fracture de l'extrémité inférieure du radius (EIR) ?","a":"<p>À l'inspection, on observe un <strong>œdème constant</strong> (souvent accompagné d'une ecchymose).</p><ul><li>De face, il peut y avoir une déformation en <strong>« main botte radiale »</strong> ou en <strong>« baïonnette »</strong> (par translation latérale du fragment épiphysaire avec saillie de la styloïde ulnaire) en cas de fracture déplacée.</li><li>De profil, on distingue généralement un <strong>« dos de fourchette »</strong> (fractures par compression-extension comme Pouteau-Colles ou Gérard-Marchant) ou un <strong>« ventre de fourchette »</strong> (fractures par compression-flexion comme Goyrand-Smith).</li></ul>"},{"i":"c3426607ead8","n":363,"o":"363-14","u":"Diagnostic positif","t":"Connaître les modalités du diagnostic clinique d’une fracture de l’EIR","q":"Quels sont les signes fonctionnels d'une fracture de l'extrémité inférieure du radius (EIR) ?","a":"<p>Les signes fonctionnels d'une fracture de l'EIR incluent un <strong>craquement audible</strong> lors du traumatisme et une <strong>impotence fonctionnelle totale</strong> du poignet (le patient soutient son membre traumatisé).</p>"},{"i":"c63f72c7a394","n":363,"o":"363-14","u":"Diagnostic positif","t":"Connaître les modalités du diagnostic clinique d’une fracture de l’EIR","q":"Quel est le signe pathognomonique retrouvé à la palpation lors d'une fracture de l'extrémité inférieure du radius (EIR) ?","a":"<p>À la palpation, le <strong>Signe de Laugier</strong> est caractéristique : une <strong>horizontalisation de la ligne bi-styloïdienne</strong>. Pour les fractures non déplacées, une <strong>douleur exquise métaphysaire</strong> est un signe important.</p>"},{"i":"0b52824b907b","n":363,"o":"363-15","u":"Examens complémentaires","t":"Connaître l’indication, l’objectif et la sémiologie de base des examens d’imagerie devant une fracture de l’extrémité inférieure du radius","q":"Quel est l'examen d'imagerie de première intention à réaliser devant une suspicion de fracture de l'extrémité inférieure du radius ?","a":"<p>L'examen de première intention est la <strong>radiographie du poignet</strong>.</p>"},{"i":"31a04e963759","n":363,"o":"363-15","u":"Examens complémentaires","t":"Connaître l’indication, l’objectif et la sémiologie de base des examens d’imagerie devant une fracture de l’extrémité inférieure du radius","q":"Quels sont les repères radiographiques à évaluer sur l'incidence de face du poignet en cas de fracture de l'extrémité inférieure du radius ?","a":"<p>Sur l'incidence de face, il faut évaluer :</p><ul><li>L'<strong>angle d'inclinaison de la glène radiale</strong> : normalement d'environ <strong>25°</strong> (regardant en bas, en avant et en dedans), il peut être horizontalisé en cas de fracture.</li><li>La <strong>ligne bi-styloïdienne</strong> : normalement d'environ <strong>15°</strong>, elle est horizontalisée (< 15°) en cas de fracture, caractéristique de la fracture de Pouteau-Colles.</li><li>L'<strong>index radio-ulnaire distal</strong> : normalement à environ <strong>-2 mm</strong> (ulna plus courte), il peut devenir nul ou positif en cas de fracture.</li></ul>"},{"i":"41508eed04df","n":363,"o":"363-15","u":"Examens complémentaires","t":"Connaître l’indication, l’objectif et la sémiologie de base des examens d’imagerie devant une fracture de l’extrémité inférieure du radius","q":"Dans quel cas un examen TDM est-il indiqué pour une fracture de l'extrémité inférieure du radius, et quel est son objectif ?","a":"<p>Un <strong>scanner (TDM)</strong> est indiqué en complément des radiographies dans les <strong>fractures articulaires</strong> de l'extrémité inférieure du radius. Son objectif est de réaliser un <strong>bilan précis des fragments</strong>.</p>"},{"i":"c18ae60b0087","n":363,"o":"363-15","u":"Examens complémentaires","t":"Connaître l’indication, l’objectif et la sémiologie de base des examens d’imagerie devant une fracture de l’extrémité inférieure du radius","q":"Combien d'incidences radiographiques sont classiquement réalisées pour une fracture de l'extrémité inférieure du radius, et laquelle peut être ajoutée en cas de suspicion de fracture articulaire ?","a":"<p>Classiquement, <strong>deux à trois incidences</strong> sont réalisées : la <strong>face</strong> et le <strong>profil</strong>. Une incidence de <strong>trois quarts</strong> peut être ajoutée en cas de suspicion de fracture articulaire.</p>"},{"i":"c5cecd695004","n":363,"o":"363-15","u":"Examens complémentaires","t":"Connaître l’indication, l’objectif et la sémiologie de base des examens d’imagerie devant une fracture de l’extrémité inférieure du radius","q":"Quel repère radiographique est essentiel à évaluer sur l'incidence de profil du poignet en cas de fracture de l'extrémité inférieure du radius, et quelle est sa valeur normale ?","a":"<p>Sur l'incidence de profil, il est essentiel d'évaluer l'<strong>antéversion de la glène radiale</strong>. Sa norme est de <strong>10 à 12°</strong>. En cas de fracture, elle peut être rétroversée (fracture de Pouteau-Colles ou de Gérard-Marchant) ou exagérée (fracture de Goyrand-Smith).</p>"},{"i":"07f5fbbc5115","n":363,"o":"363-16","u":"Contenu multimédia","t":"Radiographie du poignet avec fracture de Pouteau-Colles","q":"Comment se caractérise une fracture de Pouteau-Colles sur une radiographie de poignet de profil ?","a":"<p>Sur l'incidence de profil, une fracture de Pouteau-Colles présente une <strong>déformation en « dos de fourchette »</strong>, caractérisée par une <strong>bascule postérieure de l'épiphyse</strong> et une <strong>surface articulaire rétroversée</strong>.</p>"},{"i":"84c0eaef63cf","n":363,"o":"363-16","u":"Contenu multimédia","t":"Radiographie du poignet avec fracture de Pouteau-Colles","q":"Quelles sont les caractéristiques principales de la fracture de Pouteau-Colles, au-delà des signes radiologiques spécifiques à chaque incidence ?","a":"<p>La fracture de Pouteau-Colles est une fracture de l'extrémité inférieure du radius (EIR) qui est <strong>extra-articulaire</strong>, avec un <strong>déplacement dorsal du fragment distal</strong> et une <strong>styloïde ulnaire intacte</strong>.</p>"},{"i":"91dc47fc20c5","n":363,"o":"363-16","u":"Contenu multimédia","t":"Radiographie du poignet avec fracture de Pouteau-Colles","q":"Qu'est-ce qui distingue une fracture de Pouteau-Colles d'une fracture de Gérard-Marchant, selon le contenu donné ?","a":"<p>La fracture de Pouteau-Colles se distingue de la fracture de Gérard-Marchant par la <strong>styloïde ulnaire intacte</strong>. La fracture de Gérard-Marchant inclut systématiquement une fracture associée de la styloïde ulnaire.</p>"},{"i":"adadc5b3f121","n":363,"o":"363-16","u":"Contenu multimédia","t":"Radiographie du poignet avec fracture de Pouteau-Colles","q":"Comment se caractérise une fracture de Pouteau-Colles sur une radiographie de poignet de face ?","a":"<p>Sur l'incidence de face, une fracture de Pouteau-Colles présente :</p><ul><li>Une <strong>déformation en « baïonnette »</strong> (traduisant une translation latérale du fragment distal).</li><li>Une <strong>horizontalisation de la ligne bistyloïdienne</strong> (angle inférieur à <strong>15°</strong>).</li></ul>"},{"i":"5e49f01ba90c","n":363,"o":"363-17","u":"Identifier une urgence","t":"Savoir rechercher les signes de gravité immédiate","q":"Quel examen est obligatoire avant et après réduction d'une fracture de l'extrémité inférieure du radius (EIR), et que doit-il préciser ?","a":"<p>Un <strong>examen vasculo-nerveux distal est obligatoire</strong> avant et après réduction. Il doit préciser :</p><ul><li>La <strong>sensibilité du territoire du nerf médian</strong>.</li><li>La <strong>mobilité du pouce</strong>.</li><li>La <strong>coloration des doigts</strong>.</li><li>La <strong>présence et la qualité des pouls</strong> (radial et ulnaire).</li></ul>"},{"i":"6524a88057c0","n":363,"o":"363-17","u":"Identifier une urgence","t":"Savoir rechercher les signes de gravité immédiate","q":"Quelle complication mécanique immédiate spécifique et sa manifestation clinique faut-il rechercher devant une fracture de l'extrémité inférieure du radius (EIR) ?","a":"<p>Il faut rechercher une <strong>incarcération du tendon du long extenseur du pouce</strong> dans le foyer de fracture, se manifestant par une <strong>perte de l'extension active de l'inter-phalangienne du pouce</strong>.</p>"},{"i":"b442c1b511f8","n":363,"o":"363-17","u":"Identifier une urgence","t":"Savoir rechercher les signes de gravité immédiate","q":"Quelles sont les principales complications immédiates neurologiques à rechercher systématiquement devant une fracture de l'extrémité inférieure du radius (EIR) ?","a":"<p>Devant une fracture de l'EIR, il faut rechercher une <strong>compression du nerf médian</strong> due à un hématome dans le canal carpien ou à un déplacement antérieur (fracture de Goyrand-Smith).</p>"},{"i":"e05d9075d8d1","n":363,"o":"363-17","u":"Identifier une urgence","t":"Savoir rechercher les signes de gravité immédiate","q":"Quelles sont les complications cutanée et vasculaire immédiates à rechercher devant une fracture de l'extrémité inférieure du radius (EIR), et que cela implique-t-il ?","a":"<p>Il faut rechercher :</p><ul><li>Une <strong>ouverture cutanée</strong> (fracture ouverte), nécessitant de s'assurer de la <strong>vaccination anti-tétanique</strong> (SAT-VAT ou VAT-SAT).</li><li>Une <strong>atteinte vasculaire</strong>, évaluée par la <strong>prise des pouls radial, ulnaire et axillaire</strong>.</li></ul>"},{"i":"20ae85d0bd90","n":363,"o":"363-3","u":"Diagnostic positif","t":"Savoir faire le diagnostic clinique de fracture du fémur proximal","q":"Comment différencier cliniquement une fracture cervicale vraie d'une fracture trochantérienne du fémur proximal ?","a":"<p>Bien que les deux soient des fractures du fémur proximal, on les distingue cliniquement par :</p><ul><li>La <strong>localisation de la douleur</strong> : à l'<strong>aine</strong> pour la fracture cervicale vraie, au <strong>grand trochanter</strong> (avec douleur à la palpation du massif) pour la fracture trochantérienne.</li><li>L'<strong>impotence fonctionnelle</strong> : l'appui peut être possible en cas de fracture cervicale vraie peu déplacée (Garden 1/2), mais elle est <strong>totale</strong> en cas de fracture cervicale très déplacée (Garden 3/4) ou de fracture trochantérienne.</li><li>La <strong>déformation</strong> : en cas de fracture trochantérienne, on peut observer une <strong>ascension du massif trochantérien</strong>, en plus de l'attitude vicieuse classique de raccourcissement, rotation externe et adduction si la fracture est déplacée.</li></ul>"},{"i":"6c1fe59ba22b","n":363,"o":"363-3","u":"Diagnostic positif","t":"Savoir faire le diagnostic clinique de fracture du fémur proximal","q":"Quel piège diagnostique clinique est à connaître concernant l'attitude vicieuse dans le cadre d'une fracture du fémur proximal ?","a":"<p>Un piège diagnostique clinique est que l'<strong>attitude vicieuse typique</strong> (raccourcissement + adduction + rotation externe) <strong>peut manquer</strong> dans les fractures du fémur proximal <strong>peu déplacées</strong>, notamment les fractures cervicales de type <strong>Garden 1 ou 2</strong>.</p>"},{"i":"9d487bd8e393","n":363,"o":"363-3","u":"Diagnostic positif","t":"Savoir faire le diagnostic clinique de fracture du fémur proximal","q":"Quels sont les signes cliniques généraux évocateurs d'une fracture du fémur proximal ?","a":"<p>Les signes cliniques généraux évocateurs d'une fracture du fémur proximal sont :</p><ul><li>Une <strong>douleur</strong>, localisée à l'<strong>aine</strong> (fracture cervicale) ou au <strong>grand trochanter</strong> (fracture trochantérienne).</li><li>Une <strong>impotence fonctionnelle du membre inférieur</strong>, qui peut être totale ou permettre un appui partiel (selon le type de fracture et son déplacement).</li><li>Un <strong>clinostatisme</strong>, c'est-à-dire l'impossibilité de décoller le talon du plan du lit.</li><li>Une <strong>attitude vicieuse typique</strong> si la fracture est déplacée : <strong>raccourcissement + adduction + rotation externe</strong> (le bord externe du pied repose sur la table).</li></ul>"},{"i":"d58b552ca5ef","n":363,"o":"363-3","u":"Diagnostic positif","t":"Savoir faire le diagnostic clinique de fracture du fémur proximal","q":"Dans quel contexte clinique doit-on évoquer une fracture du fémur proximal chez l'adulte ?","a":"<p>Il faut évoquer une fracture du fémur proximal dans deux principaux contextes:</p><ul><li>Une <strong>chute de sa hauteur</strong> (traumatisme à basse énergie).</li><li>Un AVP (accident de la voie publique), notamment avec un <strong>syndrome du tableau de bord</strong>.</li></ul>"},{"i":"4d029b784d36","n":363,"o":"363-4","u":"Examens complémentaires","t":"Connaître l’indication, l’objectif et la sémiologie de base des examens d’imagerie devant une fracture de l’extrémité supérieure du fémur","q":"Quelle est l'indication principale des examens d'imagerie devant une suspicion clinique de fracture de l'extrémité supérieure du fémur (FESF) ?","a":"<p>L'indication principale est <strong>toute suspicion clinique</strong> de fracture de l'extrémité supérieure du fémur (FESF).</p>"},{"i":"a76037ff3be3","n":363,"o":"363-4","u":"Examens complémentaires","t":"Connaître l’indication, l’objectif et la sémiologie de base des examens d’imagerie devant une fracture de l’extrémité supérieure du fémur","q":"Que doit-on faire en cas de forte suspicion clinique de fracture de l'extrémité supérieure du fémur si les radiographies standards sont normales ou peu concluantes (par exemple Garden I ou II engrenée non déplacée) ?","a":"<p>En cas de forte suspicion clinique avec des radiographies standards normales ou peu concluantes, il faut compléter l'exploration par un <strong>scanner (TDM)</strong> ou une <strong>IRM</strong> pour rechercher un trait de fracture occulte.</p>"},{"i":"a8eb7245d988","n":363,"o":"363-4","u":"Examens complémentaires","t":"Connaître l’indication, l’objectif et la sémiologie de base des examens d’imagerie devant une fracture de l’extrémité supérieure du fémur","q":"Comment l'imagerie radiographique permet-elle de classer le déplacement d'une fracture cervicale du fémur (FESF) et que signifie une fracture de Garden I ?","a":"<p>Le déplacement est classé selon la classification de <strong>Garden</strong>. Une fracture de <strong>Garden I</strong> est une fracture <strong>incomplète</strong>, avec la corticale médiale préservée et une impaction en valgus.</p>"},{"i":"c4fb28e99aa1","n":363,"o":"363-4","u":"Examens complémentaires","t":"Connaître l’indication, l’objectif et la sémiologie de base des examens d’imagerie devant une fracture de l’extrémité supérieure du fémur","q":"Quels sont les objectifs des examens d'imagerie devant une fracture de l'extrémité supérieure du fémur ?","a":"<ul><li>Confirmer la fracture.</li><li>Localiser la fracture (cervicale vs. trochantérienne).</li><li>Évaluer le déplacement (classification de <strong>Garden</strong>).</li><li>Évaluer le trait de fracture (classification de <strong>Pauwels</strong>, recherche de comminution).</li></ul>"},{"i":"fa3a84cb9906","n":363,"o":"363-4","u":"Examens complémentaires","t":"Connaître l’indication, l’objectif et la sémiologie de base des examens d’imagerie devant une fracture de l’extrémité supérieure du fémur","q":"Quelles sont les incidences radiographiques de référence à demander pour l'exploration d'une suspicion de fracture de l'extrémité supérieure du fémur et que permettent-elles d'analyser ?","a":"<ul><li><strong>Bassin de face</strong> : offre une vue d'ensemble et permet une comparaison avec la hanche saine.</li><li><strong>Hanche de face</strong>, membre en rotation interne de <strong>10°</strong> : dégage une vraie face du col fémoral.</li><li><strong>Profil chirurgical</strong> (ou profil inguinal, profil d'Arcelin) : analyse le déplacement postérieur et la comminution.</li></ul>"},{"i":"00eef7c64aea","n":363,"o":"363-5","u":"Contenu multimédia","t":"Radiographie de la hanche droite de face d’une fracture du col fémoral","q":"Quelle est la sémiologie radiographique d'une fracture du col fémoral de stade Garden II ?","a":"<p>Une fracture du col fémoral de stade Garden II est caractérisée par une <strong>fracture complète</strong> mais <strong>non déplacée</strong>, les travées céphaliques et cervicales restent <strong>parallèles</strong>.</p>"},{"i":"05fbbc3255b4","n":363,"o":"363-5","u":"Contenu multimédia","t":"Radiographie de la hanche droite de face d’une fracture du col fémoral","q":"Comment interpréter radiographiquement une fracture du col fémoral de stade Garden I ?","a":"<p>Une fracture du col fémoral de stade Garden I correspond à une <strong>fracture incomplète</strong>, avec une <strong>corticale médiale préservée</strong>. Elle est <strong>non déplacée</strong> et présente une <strong>impaction des travées céphaliques en valgus</strong>.</p>"},{"i":"59b9bfa786e9","n":363,"o":"363-5","u":"Contenu multimédia","t":"Radiographie de la hanche droite de face d’une fracture du col fémoral","q":"Comment reconnaître radiographiquement une fracture du col fémoral de stade Garden IV ?","a":"<p>Une fracture du col fémoral de stade Garden IV est une <strong>fracture complète avec un déplacement complet</strong>. Les <strong>travées céphaliques et cervicales redeviennent parallèles</strong> en raison de la rotation du fragment céphalique.</p>"},{"i":"92d88a7d47f2","n":363,"o":"363-5","u":"Contenu multimédia","t":"Radiographie de la hanche droite de face d’une fracture du col fémoral","q":"Décrivez la sémiologie radiographique d'une fracture du col fémoral de stade Garden III.","a":"<p>Une fracture du col fémoral de stade Garden III est une <strong>fracture complète déplacée</strong>. Elle se manifeste par un <strong>déplacement partiel</strong> et une <strong>varisation des travées céphaliques</strong> par rapport aux travées cervicales.</p>"},{"i":"e01b078fd70a","n":363,"o":"363-5","u":"Contenu multimédia","t":"Radiographie de la hanche droite de face d’une fracture du col fémoral","q":"Quel est le risque principal associé à l'augmentation du stade de Garden dans les fractures du col fémoral ?","a":"<p>Plus le stade de Garden augmente (en particulier de III à IV), plus le <strong>risque vasculaire</strong> et de <strong>nécrose avasculaire de la tête fémorale</strong> est élevé.</p>"},{"i":"4f1f2fb2d66c","n":363,"o":"363-8","u":"Identifier une urgence","t":"Comprendre l’urgence de la prise en charge des fractures du fémur proximal","q":"Quel est le délai de prise en charge pour une fracture intracapsulaire déplacée du col fémoral chez un patient jeune (< 60 ans) ?","a":"<p>Il s'agit d'une <strong>urgence</strong> nécessitant une réduction et une ostéosynthèse au plus tôt afin de tenter de <strong>sauver la tête fémorale</strong>.</p>"},{"i":"c178d4c0b2cc","n":363,"o":"363-8","u":"Identifier une urgence","t":"Comprendre l’urgence de la prise en charge des fractures du fémur proximal","q":"Pourquoi la prise en charge chirurgicale des fractures du fémur proximal chez le sujet âgé est-elle une urgence ?","a":"<p>L'urgence n'est pas la fracture elle-même, mais la <strong>remise en charge précoce</strong>. L'objectif est de limiter les <strong>complications du décubitus</strong> et la <strong>décompensation des comorbidités</strong>.</p>"},{"i":"c720bde0080b","n":363,"o":"363-8","u":"Identifier une urgence","t":"Comprendre l’urgence de la prise en charge des fractures du fémur proximal","q":"Quelle est l'incidence du délai opératoire sur la mortalité des fractures du fémur proximal chez le sujet âgé ?","a":"<p>Chez le sujet âgé, un <strong>délai opératoire > 48 heures</strong> est le principal facteur de surmortalité.</p>"},{"i":"cfac7e61a7e7","n":363,"o":"363-8","u":"Identifier une urgence","t":"Comprendre l’urgence de la prise en charge des fractures du fémur proximal","q":"Quel est le délai de prise en charge pour une fracture extracapsulaire chez un patient jeune (< 60 ans) ?","a":"<p>Il s'agit d'une <strong>urgence différée</strong>, compte tenu d'un risque d'ostéonécrose considéré comme faible dans ce type de fracture chez le patient jeune.</p>"},{"i":"d24b955aeccb","n":363,"o":"363-8","u":"Identifier une urgence","t":"Comprendre l’urgence de la prise en charge des fractures du fémur proximal","q":"Quel est le délai de prise en charge chirurgicale recommandé pour une fracture du fémur proximal chez le sujet âgé ?","a":"<p>La chirurgie doit être réalisée <strong>dans les 48 heures</strong>. Au-delà de ce délai, une surmortalité est observée.</p>"}]};